quests[66442] = { id = 66442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geistige Betätigung", description = "Wir haben jetzt vier Kugeln der Elemente! Lasst uns sehen, welche Hypothese sich als richtig erweist!", sourceObjective = "Helft, die Kugeln an der Titanenbarriere in den Ruinen des Lebensgewölbes auszuprobieren.", completion = "Meine ursprüngliche Hypothese passt. Die Elemente sind zusammen effektiver.", sourceObjectiveStatus = "unverified-source-field" }
quests[66443] = { id = 66443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf an den Jagdtrupp", description = "<Der schallende Ruf eines Jagdhorns dröhnt aus dem Zentrum des Dorfes und ruft die Jäger von Uktulut zur Alarmbereitschaft auf.\n\nIhr solltet Euch das ansehen.>", sourceObjective = "Untersucht den Anlass für den Jagdruf.", progress = "Das könnte unsere einzige Möglichkeit sein, sie dort zu treffen, wo es wehtut!", completion = "Wenn der Häuptling sich der Aufgabe nicht annimmt, werde ich diesen Djaradin höchstpersönlich in Stücke schlagen! Versprochen!", sourceObjectiveStatus = "unverified-source-field" }
quests[66444] = { id = 66444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Solange das Eisen heiß ist", description = "Ich habe auf dem Weg nach unten mit unseren Spähern gesprochen. Sie sagen, dass dieser Djaradin, Zhurtan der Flussbrüher, sein abscheuliches Ritual südwestlich von hier begonnen hat... in der Nähe der Wasserfälle, wo viele unserer Ottuks ihre Nester bauen.\n\nWenn sie das Wasser jetzt flussaufwärts zum Kochen bringen, werden sie wohl versuchen, sich uns noch schneller zu entledigen. Wir wären gezwungen, zu verhungern oder abzuziehen... Und wir werden beides nicht tun.\n\nSie drängen uns wie Feiglinge, fürchten einen echten Kampf. Dann müssen wir den Kampf dieses Mal wohl zu ihnen bringen, findet Ihr nicht auch?", sourceObjective = "Tötet Zhurtan den Flussbrüher.", completion = "Unser Fluss... und unsere Leute... hätten ohne Eure Hilfe nicht gerettet werden können.\n\nDer Uktulutstamm steht tief in Eurer Schuld.", sourceObjectiveStatus = "unverified-source-field" }
quests[66445] = { id = 66445, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehre den Gefallenen", description = "Die Djaradin haben keinen Respekt vor der Heiligkeit der Zitadelle und den toten Körpern unserer Art! Sie brechen ihnen die Knochen und berauben sie ihrer persönlichen Gegenstände, um sie als Trophäen zu behalten.\n\nSolch eine Respektlosigkeit nagt am Herz eines jeden stolzen schwarzen Drachen. Sie haben es verdient, mit Ehre behandelt zu werden.\n\nErkämpft Euch die Gegenstände zurück, die die Djaradin von den Leichen unserer Gefallenen gestohlen haben.", sourceObjective = "Holt 8 Ring des gefallenen Beschützers, 3 Flammenklinge des Erdwächters und 1 Horn von Scorxia zurück", progress = "Habt Ihr die Gegenstände der Gefallenen sichern können?", completion = "Die Erinnerungen an jene, die gefallen sind, werden nicht vergessen. Nicht dank der Djaradin.\n\nWir werden diese Gegenstände sicher verwahren und den Toten gedenken.", sourceObjectiveStatus = "unverified-source-field" }
quests[66447] = { id = 66447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jenseits der Barriere", description = "Die Barriere ist weg! Schauen wir uns das Gewölbe an!", sourceObjective = "Untersucht das Lebensgewölbe in den Ruinen des Lebensgewölbes.", progress = "Im Gewölbe gibt es viel zu untersuchen, aber wir sollten zur Sicherheit klein anfangen!", completion = "Ich denke, von nun an sind wir sicher, {name}. Habt Dank. Es ist Zeit, dass die Expedition tiefer gräbt!\n\n\n\nNur ein bisschen Schamanenhumor. Zu früh?", sourceObjectiveStatus = "unverified-source-field" }
quests[66448] = { id = 66448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wegbehüter auf Abwegen", description = "Die Wegbehüter sorgen auf den Straßen von Thaldraszus für Sicherheit, so lange ich zurückdenken kann. Es ist eine Pflicht, die meine Familie seit Generationen ehrenhaft erfüllt.\n\nLeider scheint sich meine Schwester Alvi in letzter Zeit nicht sonderlich für diese Ehre zu interessieren. Eigentlich sollte sie mir hier jeden Morgen Bericht erstatten, aber ich habe seit über einem Tag nichts mehr von ihr gehört.\n\nWenn Ihr östlich von hier eine bronzene Drakonide beim Tagträumen und Faulenzen antrefft, habt Ihr meine Schwester gefunden. In dem Fall würde ich Euch bitten, sie zu mir zu schicken. Ansonsten müsste ich sie wohl oder übel selbst aufsuchen.", sourceObjective = "Findet Wegbehüterin Alvi.", completion = "Oh, du liebe Güte, Besuch! Verzeiht, ich bin gerade nicht ganz bei mir.", sourceObjectiveStatus = "unverified-source-field" }
quests[66449] = { id = 66449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elementare Machenschaften", description = "Staubbinder der Qalashi wollen unsere Welpen gefangen nehmen. Offenbar plant ihr Anführer, sie für finstere Machenschaften einzusetzen. Das dürfen wir nicht zulassen!\n\nDoch die Djaradin sind nicht der einzige Gegner. Unsere Welpen werden auch von Phönixen verfolgt, die noch gefährlicher sind.\n\nIhr müsst die Welpen beschützen und die Gegner ausschalten. Osoria hilft Euch.", sourceObjective = "Rettet 8 gefährdete Welpen und eliminiert 12 Sengklauenphönixe sowie Aschebinderin Tornecha.", completion = "Selbst der kleinste schwarze Drachenwelpe muss beschützt werden. Unsere Zukunft hängt davon ab.\n\nIhr habt heute etwas Großes vollbracht.", sourceObjectiveStatus = "unverified-source-field" }
quests[66456] = { id = 66456, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine giftige Palette", description = "Ich bin vielleicht nicht besonders gut bei meiner Arbeit, aber wenigstens habe ich aufgepasst, als ich gelernt habe, wie man sie macht. Jede Wegbehüterin, die etwas auf sich hält, weiß, wie man ein ordentliches Gegengift braut. Ich brauche nur genug Gift für die richtige Mischung.\n\nNori hat gesagt, die Speere der Tarasek, die sie angegriffen haben, wären damit bedeckt gewesen. Findet sie und bringt mir ihre Speere. Wenn mein Gefühl stimmt, werde ich aus den Rückständen an den Speerspitzen ein Gegengift herstellen können.\n\nIch hoffe nur, wir haben genug Zeit.", sourceObjective = "Sammelt 8 vergiftete Speere.", progress = "Beeilt Euch, {name}. Ich halte Nori stabil, aber das Gift breitet sich immer weiter aus.", completion = "<Alvi nimmt die Speere, die Ihr gesammelt habt. Sie streicht vorsichtig mit ihrem Dolch über eine der Klingen und entfernt damit einen Film von klebrigem Harz.>\n\nGenau, wie ich dachte. Habt Dank, {name}. Das sollte für ein Gegengift ausreichen, und ich glaube, ich weiß auch, wo dieses Gift herkommt.", sourceObjectiveStatus = "unverified-source-field" }
quests[66457] = { id = 66457, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schluss mit der blauen Periode", description = "Die Glutzähne folgen alle einem übergroßen Koloss, den ich Blauschuppe nenne. Er war schon immer von der aggressiveren Sorte, aber bisher hat er seinen Haufen von Plünderern von den Hauptstraßen ferngehalten. Sicher, sie waren territorial, aber nicht feindselig. Bis jetzt zumindest.\n\nBlauschuppe muss für diese plötzliche Eskalation verantwortlich sein. Findet ihn und streckt ihn nieder.", sourceObjective = "Tötet Blauschuppe.", completion = "Nachdem wir uns um Blauschuppe gekümmert haben, bezweifle ich, dass wir bald noch einmal mit organisierten Angriffen der Tarasek zu tun haben.\n\nJetzt müssen wir uns nur noch um das Gift kümmern.", sourceObjectiveStatus = "unverified-source-field" }
quests[66458] = { id = 66458, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vermächtnis von Tyr: Geheimnisse der Vergangenheit", description = "Damit Raszageth die anderen Inkarnationen nicht befreien kann, müssen wir die Macht der Aspekte wiederherstellen.\n\nUnglücklicherweise sind die Titanen mit anderen Dingen beschäftigt und Hüter Tyr ist schon lange tot.\n\nKönigin Alexstrasza hat jedoch einen Plan vorgebracht. In den Tiefen des Ödlands liegt eine Titanenanlage namens Uldaman. Anscheinend haben Verbündete Tyrs dort eine Scheibe mit seinen Erinnerungen versteckt.\n\nJedoch wurde diese Anlage angeblich von Troggs überrannt. Sammelt Eure Verbündeten und begebt Euch nach Uldaman. Beschlagnahmt die Scheibe im Namen der Drachenkönigin!", sourceObjective = "Geht nach Uldaman: Vermächtnis von Tyr im Ödland und besorgt die Scheibe.", completion = "Ewige Drachen? Die führen stets etwas im Schilde.\n\nIch werde die Drachenkönigin darüber informieren, dass sie die Macht der Aspekte auf andere Weise wiederherstellen muss.", sourceObjectiveStatus = "unverified-source-field" }
quests[66459] = { id = 66459, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Feld der Wildheit: Schrecken des Sumpfes!", description = "Willkommen, alle zusammen, auf den Feldern der Wildheit!\n\nDieses Feld wird gewöhnlich für traditionelle Anlässe genutzt, aber die Zentauren haben mir großzügigerweise erlaubt, während der Nebensaison hier meinen Laden aufzubauen. Sie meinen, damit würde ich ihre Stärke auf die Probe stellen und ihnen Ehre bringen.\n\nWollt Ihr den Titel des Champions gewinnen? Lasst mich wissen, wenn Ihr bereit seid, dann könnt Ihr die Einführungsherausforderung annehmen.", sourceObjective = "Besiegt Maneet.", progress = "Sprecht mit Gurgthock, um die Runde zu beginnen, und besiegt dann den ersten Herausforderer auf dem Feld der Wildheit.", completion = "Für die erste Runde nich' schlecht! Aber wir fang'n grade erst an. Sprecht wieder mit Gurgthock, wenn Ihr bereit seid, mit der zweiten Runde anzufang'.", sourceObjectiveStatus = "unverified-source-field" }
quests[66460] = { id = 66460, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Feld der Wildheit: Fürst des Verfalls!", description = "Ich habe versucht, einen dieser garstigen Gnolle für diesen Spießrutenlauf zu bekommen. Leider weiß keiner meiner Kollegen, wie man mit ihnen spricht.\n\nWir konnten aber eine ihrer merkwürdigen Schöpfungen fangen. Die sollte als angemessener Gegner herhalten! Gebt Bescheid, wenn Ihr bereit seid, mit der zweiten Runde zu beginnen!", sourceObjective = "Besiegt Nachtfaul.", progress = "Worauf wartet Ihr noch? Sprecht mit Gurgthock, um die mit der Runde anzufang'n, und besiegt dann den zweit'n Herausforderer auf dem Feld der Wildheit.", completion = "Ich bin froh, dass Ihr mit der Kreatur so kurz'n Prozess gemacht habt. Der Gestank wurd' sogar schon auf'm Podium übel.", sourceObjectiveStatus = "unverified-source-field" }
quests[66461] = { id = 66461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Feld der Wildheit: Gegner aus dem Vulkan!", description = "Einer der ersten Freiwilligen für diesen Wettkampf kam von der Küste des Erwachens. Ein großer Djaradin, deutlich weniger wütend als seine Verwandten.\n\nEr scheint den Kampf als Sport zu genießen. Hey, mir soll's recht sein.", sourceObjective = "Besiegt Ceeqa den Friedensstörer.", progress = "Keiner feiert seinen Auftritt so wie Ceega. Ihr müsst mit Gurgthock sprechen, um mit der Runde anzufang'n. Besiegt dann den dritt'n Herausforderer auf dem Feld der Wildheit.", completion = "Was für 'ne Schau! Ich konnt bis hierher spüren, wie die Funken sprüh'n!", sourceObjectiveStatus = "unverified-source-field" }
quests[66462] = { id = 66462, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Feld der Wildheit: Verloren im Traum!", description = "Wisst Ihr, für die Dracheninseln sieht man hier ganz schön wenige Drachen. Aber wir haben ein Drachkinduo, das angefragt hat, sich zusammen für den Wettkampf eintragen zu dürfen.\n\nSie wirken begierig, sich zu beweisen, also viel Glück!", sourceObjective = "Besiegt Sherath und Taresh.", progress = "Ihr müsst mit Gurgthock sprech'n, um die Runde zu beginn'. Besiegt dann die vierten Herausforderer auf dem Feld der Wildheit.", completion = "Wassis? Ist der Kampf vorbei? Ich muss aus irgend'nem Grund mittendrin eingeschlaf'n sein.\n\nIch schätz mal, Ihr habt gewonn', wenn Ihr hier vor mir steht?", sourceObjectiveStatus = "unverified-source-field" }
quests[66463] = { id = 66463, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Feld der Wildheit: Elementare Rache!", description = "Eine Änderung der Aufstellung in letzter Minute! Irgendein Primalistenangeber will dem Wettkampf beitreten, um Euch gegenüberzutreten. Und ich sage nicht nein zu einem wütenden Elementardrachen.\n\nIch bin sicher, Ihr schafft das. Und wenn nicht... Dafür habt Ihr ja die Verzichtserklärung unterzeichnet, oder?", sourceObjective = "Besiegt den Champion der Primalisten.", progress = "Ihr müsst mit Gurgthock sprechen, um die Runde zu beginnen, und besiegt dann den fünften Herausforderer auf dem Feld der Wildheit.", completion = "Ich verstehe jetzt die Gerüchte, die ich über Euch und Eure Crew gehört habe. Ihr seid weiter gekommen, als ich je erwartet hätte.", sourceObjectiveStatus = "unverified-source-field" }
quests[66464] = { id = 66464, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Feld der Wildheit: Meister der Jagd!", description = "Jetzt ist es also so weit. Ihr und Eure Crew habt das große Los gezogen. Ein Kampf gegen den Champion, Jagdmeisterin Amaa selbst. Klopft Euch aber noch nicht auf die Schulter. Sie ist unbarmherzig. Es war schön, Euch gekannt zu haben.\n\nWenn sie Euch erledigt hat, kann ich dann Eure Sachen haben?", sourceObjective = "Besiegt Jagdmeisterin Amaa.", progress = "Ihr müsst mit Gurgthock sprechen, um die Runde zu beginnen, und besiegt dann den letzten Herausforderer auf dem Feld der Wildheit. Viel Glück.", completion = "Ihr seid als Kämpfer ziemlich beeindruckend und furchterregend. Die Zentauren haben viel Ehrfurcht vor Euch. Gurgthock kocht vor Wut, weil er seinen Hof auf Amaa und nicht auf Euch gesetzt hat. Die große Belohnung gehört Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[66465] = { id = 66465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kurz geschnappt", description = "Selbst nach dem Tod ihres Anführers werden die Tarasek nicht aufhören, ihre vergifteten Speere zu nutzen, und wenn wir sie noch so höflich bitten. Ich kann nicht riskieren, dass auch nur eine dieser Waffen gegen einen ahnungslosen Reisenden eingesetzt wird.\n\nSie müssen alle vernichtet werden. Wenn Ihr keine Lager bei den Becken gesehen habt, dann bewahren die Glutzähne ihre Speere wohl näher an der Quelle auf.\n\nEs wird nicht noch einmal jemand wegen meiner Achtlosigkeit verletzt werden. Sucht die Höhle auf und zerstört alle Waffenlager, die Ihr finden könnt.", sourceObjective = "Zerstört 8 Giftspeervorräte.", completion = "Die Passage ist viel sicherer ohne diese ganzen vergifteten Speere.\n\nIhr habt mit Euren heutigen Taten für die Sicherheit einer Menge Leute gesorgt, {name}. Die Wegbehüter stehen in Eurer Schuld. Und ich ebenso.", sourceObjectiveStatus = "unverified-source-field" }
quests[66467] = { id = 66467, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kunst imitiert das Leben", description = "Als ich das letzte Mal in dieser Höhle war, habe ich eine riesige Blume gezeichnet, die einen ekelhaften, dickflüssigen Saft absonderte. Das ist eine meiner besten Zeichnungen, das würde ich nie vergessen.\n\nWas an diesen Tarasekspeeren haftet, ist der Saft eben jener Blume, da bin ich mir sicher. Sie müssen angefangen haben, ihn als Gift für ihre Waffen zu verwenden.\n\nEs ist eine wunderschöne Blume und sie töten zu müssen, ist eine wahre Schande. Aber uns bleibt keine Wahl, wir müssen die Tarasek daran hindern, das Gift für ihre Waffen zu verwenden. {name}, ich bitte Euch, merzt diese Blume aus und setzt all dem ein Ende.", sourceObjective = "Erlegt den großen Giftspross.", completion = "Habt Dank, {name}. Die Tage, in denen die Glutzähne noch Gift ernten konnten, sollten vorbei sein, nachdem wir ihnen ihre Quelle abgerungen haben.\n\nIch beginne zu verstehen, dass ich keine Wegbehüterin sein muss, um in dieser Welt einen Unterschied zu machen. Ich werde meinen Posten aufgeben und mich ganz der Kunst widmen. Hoffentlich werde ich eines Tages die Gelegenheit haben, die schönsten Ausblicke der Dracheninseln festzuhalten.\n\nIch hoffe nur, meine Schwester hat Verständnis.", sourceObjectiveStatus = "unverified-source-field" }
quests[66468] = { id = 66468, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was einst Unser war", description = "<Thadezus spottet über Euren Ansatz.>\n\nSeid Ihr <ein Sterblicher, der/eine Sterbliche> die; auch was tut? Sonst geht uns besser aus dem Weg, {class}!\n\nIch habe eine Menge guter Soldaten an diese Primalisten verloren.\n\nWir haben eine Idee, was sie vorhaben, doch zunächst müssen wir den Feind in die Flucht schlagen und jene retten, die unter meinem Kommando stehen.", sourceObjective = "Besiegt die Primalisten, die den Rundblick der Gelikyr besetzt haben.", progress = "Habt Ihr die Primalisten aufgehalten oder muss ich das selbst in die Hand nehmen?", completion = "<Sharnax starrt auf Euch herab.>\n\nHmm... Wie es scheint, besitzt Ihr mehr Können, als der Kommandant Euch zu Beginn zugetraut hat.\n\nEs gibt noch mehr zu tun, bevor der Tag vorbei ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[66470] = { id = 66470, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Vorstoß", description = "<Sharnax kratzt sich am Kinn.>\n\nDer Kommandant hatte recht. Die Primalisten rufen Verstärkungen aus den Elementarebenen.\n\n<Sharnax lächelt.>\n\nEs wäre eine Schande, wenn ihren Portalen etwas zustoßen würde, {class}.", sourceObjective = "Erhaltet nebelberührte, irdene und eisgeschmiedete Portalsteine und schließt die 3 Elementarportale.", progress = "Wir müssen diese Portale schließen.", completion = "Scheint, als hättet Ihr es in einem Stück geschafft.", sourceObjectiveStatus = "unverified-source-field" }
quests[66471] = { id = 66471, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prima Planung", description = "Der Kommandant hat mich dazu beordert, einen Vorposten zu errichten und dabei jeglichen Widerstand auszumerzen. Es war allerdings erst im Nachhinein, nachdem ich sie alle erledigt hatte, dass mir etwas bewusst wurde.\n\n<Sharnax stößt einen langen Seufzer aus.>\n\nDie Primalisten haben über Tyrhold geredet.\n\nIch bezweifle, dass Ihr aus denen noch ein Wort rausbekommt. Ihr müsst dennoch für mich herausfinden, wie ihre Pläne aussehen.", sourceObjective = "Sammelt 7 Befehle der Primalisten von Primalisten in der Nähe auf der oberen Terrasse des Rundblicks der Gelikyr.", progress = "Hab Ihr etwas, das wir dem Kommandanten zeigen können?", completion = "Das ist genau, was wir gebraucht haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[66472] = { id = 66472, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prima Listen", description = "Die Portale sind geschlossen, die Elementare getötet und die Primalisten aufgehalten... vorerst.\n\n<Sharnax lacht.>\n\nGibt es irgendetwas, das wir nicht können, {class}? Ich schätze, die Zeit wird es uns zeigen.\n\nBringt die Pläne zum Kommandanten. Er wird sicherlich erfreut sein, zu hören, dass wir erfolgreich waren.", sourceObjective = "Liefert das Bündel mit Primalistenbefehlen an Kommandant Thadezus auf der Brücke am Rundblick der Gelikyr.", progress = "<Thadezus starrt Euch an.>\n\nWas wollt Ihr, {class}?", completion = "<Thadezus macht eine unangenehm lange Pause.>\n\nAllis und ich hatten schon Wetten darauf abgeschlossen, ob Ihr es schaffen würdet, {class}.\n\n Ich bin froh, dass Ihr erfolgreich wart.", sourceObjectiveStatus = "unverified-source-field" }
quests[66473] = { id = 66473, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Land erwacht", description = "Die Scheusale in dieser Höhle waren zu viel für mich.\n\n<Sharnax hustet schwer.>\n\nIch habe gesehen, wozu Ihr imstande seid.\n\nIhr müsst diese Elementare für mich töten, bevor sie ihr volles Potenzial entfalten. Wir dürfen nicht zulassen, dass die Primalisten die Kontrolle über Tyrhold erlangen!", sourceObjective = "Besiegt den urzeitlichen Zorn und den urzeitlichen Hagel am Rundblick der Gelikyr.", completion = "Vielen Dank für alles, was Ihr für uns getan habt, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[66482] = { id = 66482, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trophäenjagd: Erdschlund" }
quests[66484] = { id = 66484, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kennt Euren Feind: Protodrachen", description = "Das Gebiet ist voll von diesen mächtigen Bestien! Glücklicherweise hat das Untersuchungsfernrohr Euch ermöglicht, einige Schwachstellen zwischen ihren harten Schuppen zu finden. Ihr könnt Euch auch ein paar Tricks einfallen lassen, um ihren scharfen Klauen und Zähnen auszuweichen.", sourceObjective = "Jagt ein paar Protodrachen im Gebiet um das Hohe Blätterdach.", sourceObjectiveStatus = "unverified-source-field" }
quests[66488] = { id = 66488, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Frigellus", description = "<Die Schrift der Seite leuchtet in einem sanften blauen Licht.>\n\nDer Elementar Frigellus, einst ein geliebtes Spielzeug von Malygos, litt unter der Vernachlässigung durch seinen Herrn.\n\nWährend dieses einst glückliche Dorf immer weiter zerfiel, wurde das neckische und verspielte Wesen von den Übeln, die dieses Land plagen, entstellt und verdreht.\n\nBitte neutralisiert dieses Wesen.\n\nTeilt Euren Erfolg anschließend dem Hüter Cynegos mit.", sourceObjective = "Tötet Frigellus in der Nähe von Lager Antonidas.", completion = "Lasst uns hoffen, dass in diesem Gletscher nicht noch mehr Überraschungen warten.", sourceObjectiveStatus = "unverified-source-field" }
quests[66489] = { id = 66489, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verteidigung aufstellen", description = "Der Hüter Cynegos und ich hatten gerade über die Auswirkungen des Angriffs der Primalisten auf die Pläne zum Angriff auf den Kobaltkonvent gesprochen, und ich hatte eine Idee.\n\n<Celeste holt aus den Tiefen ihres Gewandes einen Zauberstab hervor.>\n\nNehmt meinen Stab und ermächtigt ihre Waffen!\n\nEin bisschen Feuer sollte genau das Richtige sein...", sourceObjective = "Ermächtigt Azurblaue Verteidiger in Lager Antonidas.", progress = "Wurden sie ausreichend verzaubert?", completion = "Fantastische Arbeit!\n\nNachdem wir ihren Angriff auf das Lager zurückschlagen konnten, ist es unbedingt notwendig, die Primalisten in der Defensive zu halten.\n\nNun gebt mir bitte meinen Zauberstab zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[66493] = { id = 66493, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ab dafür!", description = "<Ihr hört gedämpfte Stimmen vom anderen Ende des Portals.>\n\nHey! Hey, Ihr da!\n\nIch habe Post für unsere Auszubildenden im Außeneinsatz: Hilfspakete, Geschenke, Dinge, die sie per magischen Kurier bestellt haben...\n\nNormale Standardzustellung.\n\nWürdet Ihr mir den Gefallen tun und sie austeilen?", sourceObjective = "Werft Pakete zu den Lehrlingen der Kirin Tor im Lager Antonidas.", completion = "Gut gemacht! Keine Sorge... Es ist die Schuld des Kuriers, wenn ein Paket nicht als \"zerbrechlich\" markiert wurde.", sourceObjectiveStatus = "unverified-source-field" }
quests[66500] = { id = 66500, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wege des Sehens", description = "Wir machen gar nichts! Wir machen rein gar nichts!\n\nEinen Moment...\n\nIhr seht ziemlich wichtig aus, {race}... Möchtet Ihr ein Geheimnis wissen?\n\nWie sich herausstellt, sind diese Ruinen voller magischer Kunst! Und wir können sie sehen!\n\n<Stiebitz streckt stolz die Brust raus.>\n\nIch kann Euch zeigen, wie Ihr sie auch sehen könnt! Aber... erzählt Noriko bitte noch nichts davon.", sourceObjective = "Deckt antike Abbildungen im Lager Antonidas auf.", progress = "Noriko hat gesagt, dass wir uns aus Ärger raushalten sollen. Keine Ahnung, wie das geht, um ehrlich zu sein.", completion = "Malygos und Sindragosa, hm? Nie von ihnen gehört. Klingt allerdings, als wären sie ganz schön verliebt gewesen.\n\nIch frage mich, wer die hiergelassen hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[66503] = { id = 66503, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus Nächstenliebe", description = "Ah, wie ich sehe, haben Euch meine Lehrlinge in ihre kleinen Spiele verwickelt.\n\n<Noriko kichert.>\n\nEs scheint, als wären sie... und auch Ihr... da auf etwas gestoßen. Das Geheimnis dieser Ruinen gibt sich uns langsam zu erkennen. Und es steckt mehr dahinter als nur verblasste Abbildungen und Lieder...\n\nEtwas ruft von diesem Turm.\n\nIch sehe die Faszination in Euren Augen. Geht. Ihr habt meine Erlaubnis.\n\nIch bin gespannt, was Ihr findet.", sourceObjective = "Untersucht die Spitze des verfallenen Turms im Lager Antonidas.", completion = "Die eigene Welt verfallen zu sehen und sie für immer verloren zu glauben...\n\nIch kann es mir nicht vorstellen.\n\nWir müssen dem gedenken.", sourceObjectiveStatus = "unverified-source-field" }
quests[66504] = { id = 66504, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Splitter kristallisierten Manas", description = "<Der kleine, blaue Kristall vibriert leicht bei Berührung und gibt dann einen tiefen Ton von sich, der wie ein entferntes Lied klingt. Die Worte hallen wie eine sanfte Melodie in Eurem Kopf.>\n\nLathos wird das interessant finden.", sourceObjective = "Bringt den Kristall zu Lathos.", sourceObjectiveStatus = "unverified-source-field" }
quests[66507] = { id = 66507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Winterhauchgeschenk", sourceObjective = "Auf dem Schildchen am Geschenk steht:\n\nFrohe Feiertage, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[66508] = { id = 66508, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein leicht geschütteltes Geschenk", sourceObjective = "Dieses Geschenk sieht aus, als wäre es schon ein paar Mal geschüttelt worden. Auf dem Kärtchen steht:\n\nFür {name}, ein ganz besonderer {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[66509] = { id = 66509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paranoid 1", description = "Agura hat mich hierhergeschickt, um Blumen gegen meine Ängstlichkeit zu pflücken. Aber da sind lauter Kreaturen, die mir schreckliche Angst einjagen." }
quests[66511] = { id = 66511, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angesehen bei den Tuskarr von Iskaara", description = "Ihr beweist immer wieder, dass Ihr ein integrales Mitglied unserer Gemeinschaft seid.\n\nUm das zu würdigen, habe ich einen Vorratsbeutel für Euch vorbereitet. Trefft mich in Iskaara.", sourceObjective = "Sprecht mit Murik in Iskaara.", completion = "Erneut, wir können Euch nicht genug danken, und diese Vorräte werden diesem Dank nicht gerecht, aber wisst bitte, dass Eure Hilfe uns sehr viel bedeutet!", sourceObjectiveStatus = "unverified-source-field" }
quests[66513] = { id = 66513, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausflug auf festem Boden", description = "Vielleicht sollten wir uns ein Bild von dieser Stadt machen, wenn das unsere neue Heimat werden soll. Eine Aufklärungsmission sozusagen.\n\nGeht. Schaut, was dieser Ort zu bieten hat. Ich werde Furorion folgen und versuchen, zu helfen, wo ich kann.\n\nVersucht allerdings, die Einheimischen so wenig wie möglich aufzuscheuchen. Ich bezweifle, dass viele von ihnen an den Anblick von Drachen unter ihnen gewöhnt sind.\n\nTrefft Euch mit uns, sobald Ihr das Gebiet ausgekundschaftet habt.", sourceObjective = "Erkundet Sturmwind.", completion = "Die Allianz hat uns hier in Sturmwind Asyl gewährt.\n\nKlingt nach einem ziemlich interessanten Ort.", sourceObjectiveStatus = "unverified-source-field" }
quests[66516] = { id = 66516, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Banale Edelsteine, wohl kaum!", description = "Was für eine Verschwendung. Die Djaradin dieses Landes nutzen mächtige Edelsteine als banale Dekorationen, nur als Schmuck! Und das, obwohl es so viele Verwendungszwecke für Edelsteine gibt: Teleskope, Spiegel, Fokussierungspointer. Und dass unzählige Edelsteine magische Eigenschaften haben, brauche ich gar nicht erst zu erwähnen.\n\nWir müssen etwas dagegen tun. Erleichtert die Djaradin um ihre Edelsteine und bringt sie mir. Ich sorge dann dafür, dass sie eine bessere Verwendung finden. Aber passt auf Euch auf, denn die Djaradin sind erbitterte Krieger.", sourceObjective = "Sammelt 25 \"banale\" Edelsteine von den Djaradin auf den Dracheninseln für Gnoklin Quirkspule bei der Drachenschuppenexpedition.", progress = "Konntet Ihr die Edelsteine besorgen?", completion = "Diese Edelsteine haben so viel Potenzial, dass selbst Lugrah nicht wüsste, was sie mit so vielen anfangen sollte!\n\nLugrah ist die Vertreterin für Juwelierskunst des Handwerkerkonsortiums. Ich werde einen Teil der Aufzeichnungen mit Euch teilen, die sie mir geschickt hat, bevor ich gegangen bin. Sie werden Euch sicherlich helfen, Eure Studien der Juwelierskunst hier auf den Dracheninseln voranzutreiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[66517] = { id = 66517, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine neue Quelle für Waffen", description = "Diese Splitterflammen sind eine große Bedrohung für unsere Grenzen. Ihre Waffen machen mir Sorge. Sammelt so viele davon, wie Ihr könnt, dann können wir sie auf Schwächen untersuchen oder sie sogar für unsere Verteidigung nutzen.\n\nIch vertraue auf Euch. Und wenn Ihr diese Aufgabe für uns erledigt, werde ich Euch in unsere Schmiedekunst einweisen.", sourceObjective = "Sammelt 25 intakte Dracthyrwaffen von den Splitterflammen auf den Dracheninseln für Dhurrel von den Zentauren der Maruuk.", progress = "Was konntet Ihr finden?", completion = "Habt Dank. Die werden uns sehr weiterhelfen.\n\nWie versprochen habt Ihr hier eine Schriftrolle, die unsere Schmiede für Euch vorbereitet haben. Mögt Ihr mit diesem Wissen rasch lernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66523] = { id = 66523, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Esse schüren", description = "Falls Ihr nach einem Ausbilder sucht, muss ich Euch leider sagen, dass ich... äh, Ihr kein Lehrling seid! Mein Beileid. Erlaubt mir, mich vorzustellen.\n\nIch bin Hüterin Vernagos und gehöre zu den Verwaltern dieser Ruinen. Um genau zu sein, ist die Aufgabe, diesen Arbeitsplatz zu alter Pracht zu verhelfen, auf meine doch sehr müden Schultern gefallen.\n\nKönntet Ihr mir etwas zur Hand gehen? Alle Reagenzien, die ich benötige, lassen sich in der Nähe finden: Eiselementarkerne, Glutkegel, Flunkerleder...\n\nGängige und einfach zu sammelnde Materialien. Was sagt Ihr?", sourceObjective = "Sammelt Reagenzien für die Schmiede, indem Ihr Flunkerfelle, inaktive Glutkegel und kalbende Kerne im Bereich um das Lager Antonidas sammelt.", progress = "Frische Luft und magische Relikte. Kann man sich mehr wünschen? Ha!", completion = "Habt Dank, {name}. Die Glutkegel werden heiß glühen. Die Elementarkerne werden dafür sorgen, dass es nicht zu heiß wird. Und dieses Leder... ist recht abstoßend. Doch die Blasebälge, die wir daraus machen, werden mehr als ausreichend sein!\n\nJetzt brauche ich nur noch ein wenig Zeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[66524] = { id = 66524, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fotografie für Anfänger", description = "Ihr wollt also <ein berühmter Katalogisierer/eine berühmte Katalogisiererin> werden, so wie ich? Dann seid Ihr bei mir genau richtig!\n\nDas Wildreservat strotzt nur so vor Wissen, das archiviert werden will! Und wie ich das mache, wollt Ihr wissen? Natürlich mit meinem praktischen Katalogisierer 3000 Dracheninseledition, jetzt mit verbessertem Bewegungssensor!\n\nUm Erfahrung damit zu sammeln, solltet Ihr ein Protodrachenei, einen Welpen, der das Fliegen lernt, und einen jagenden Protodrachen fotografieren. Trefft mich beim uralten Protodrachenskelett westlich von hier, dann werde ich Eure Fotos bewerten.", sourceObjective = "Macht Bilder von den Protodrachen.", progress = "Macht Euch auf und katalogisiert, was das Zeug hält!", completion = "Die sind wundervoll! Ganz wundervoll! Habt Ihr das vorher schon mal gemacht?", sourceObjectiveStatus = "unverified-source-field" }
quests[66525] = { id = 66525, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wettbewebsfotografie", description = "Nachdem Ihr nun die ersten eigenen Erfahrungen mit einigen Anfängermotiven gesammelt habt, wie wäre es, wenn wir etwas Gewagteres versuchen?\n\nIch habe einen wunderschönen Protodrachen in der Gegend hinter uns fliegen sehen. Wunderschöne Hörner, Schuppen, die vor Elektrizität knistern... Vielleicht ist es das Werk der Primalisten, aber es ist zweifellos Kunst!\n\nSeht, ob Ihr ein Bild vom Protodrachen und von einigen seiner Eier schießen könnt. Vielleicht müsst Ihr ein wenig klettern, um einen guten Winkel zu bekommen!", sourceObjective = "Fotografiert ein energieerfülltes Protodrachenei und einen energieerfüllten Protodrachen.", completion = "Seht Euch das an! Die Farben kommen wunderbar zur Geltung! Sieht aus, als hättet Ihr Talent fürs Katalogisieren!", sourceObjectiveStatus = "unverified-source-field" }
quests[66526] = { id = 66526, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wildnis erhalten", description = "Das Wildreservat ist eines der wenigen Gebieten, in denen Protodrachen florieren. Aber die Primalisten stören ihre Nistgründe, indem sie Protowelpen und Protodrachen einfangen und Experimente an ihnen durchführen.\n\nZeigt ihnen keine Gnade. Macht diese Primalistenwilderer ausfindig, löscht sie aus und befreit ihre Gefangenen. Das Überleben der Protodrachen hängt davon ab!", sourceObjective = "Befreit 5 gefangene Protowelpen oder gefangene Protodrachen.", progress = "Wenn wir wollen, dass diese Kreaturen überleben, müssen wir sie beschützen.", completion = "Gut. Die Primalisten sind immer noch eine Bedrohung, aber diese Drachen sind wieder frei.", sourceObjectiveStatus = "unverified-source-field" }
quests[66527] = { id = 66527, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Professionelle Fotografie", description = "Ihr seid <der beste Fotograf, den/die beste Fotografin> die; ich je ausgebildet habe... zumindest von denen, die noch leben. Es ist ein gefährlicher Beruf.\n\nWo wir grade von Gefahren sprechen. Unser letztes Motiv ist ein großer Protodrache, von dem wir glauben, er könnte eins der nächsten Eliteraubtiere dieses Reservats werden. Geht auf Tuchfühlung und macht ein Foto!", sourceObjective = "Nutzt die vertikale Verstärkungsapparatur und fotografiert den schlummernden Protodrachen.", progress = "Keine Sorge, {name}. Ihr seid viel kompetenter als die letzte Person, die ich dort hoch geschickt habe.", completion = "Das hat jetzt nichts damit zu tun, aber Ihr habt da oben nicht zufällig eine weitere Kamera gefunden?\n\nWisst Ihr was? Vergesst, was ich gesagt habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[66528] = { id = 66528, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "König ohne Krone", description = "Dieser uralte Protodrache muss zu Lebzeiten eine atemberaubende Kreatur gewesen sein. Vielleicht die größte, die das Wildreservat je gesehen hat.\n\nAber das hat wohl nicht ausgereicht. Untersucht das Skelett genauer, damit wir vielleicht etwas über seine letzten Momente erfahren.", sourceObjective = "Untersucht das Protodrachenskelett.", progress = "Ein unglaubliches Exemplar und eine Erinnerung an unsere Ursprünge.", completion = "Also ein Kampf auf Leben und Tod mit etwas ebenso Starkem? Ich frage mich, ob er das Reservat vor Eindringlingen geschützt hat.\n\nHabt Dank, {name}. Es tut gut, den Opfern zu gedenken, die unsere Vorfahren erbracht haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[66529] = { id = 66529, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eintausend Worte", description = "Nach allem, was wir hier erfahren haben, kann ich mir kaum vorstellen, ohne ein Andenken weiterzuziehen.\n\nWärt Ihr so freundlich, ein Bild von mir und diesen Protodrachenfossilien zu machen?", sourceObjective = "Fotografiert Derwischian neben dem Protodrachenskelett.", progress = "Das wird nicht lange dauern.", completion = "Ich hoffe, eines Tages ebenso mutig für mein Volk kämpfen zu können, wie dieser Protodrache es in seinen letzten Augenblicken getan hat.\n\nNoch einmal vielen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[66534] = { id = 66534, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausflug auf festem Boden", description = "Wie es scheint, wurde unsere Ankunft doch bemerkt. Vielleicht gibt es noch Hoffnung für diese Leute.\n\nIch wende mich an Ebyssian und die Anführer der Horde, um die Sache ausbügeln. Seht Ihr Euch derweil um.\n\nSchaut mal, was dieser Ort zu bieten hat. Schließlich werden wir hier wohl einiges an Zeit verbringen.\n\nKommt anschließend zu uns. Hoffentlich haben wir bis dahin all das langweilige Zeug geklärt.", sourceObjective = "Erkundet Orgrimmar.", completion = "Aber wie war das Essen?", sourceObjectiveStatus = "unverified-source-field" }
quests[66546] = { id = 66546, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holt die Scheiben zurück", description = "Die Scheiben hier drin spiegeln das gesamte Wissen dieser Einrichtung wider. Wir müssen sie zurückholen!\n\nIch werde die Barriere mithilfe dieser Konsole deaktivieren. Es liegt an Euch, die Scheiben zu holen.", sourceObjective = "Holt die drei Scheiben zurück.", progress = "Könnt Ihr Euch das Wissen vorstellen, das diese Scheiben bergen?", completion = "Ich wusste, dass wir uns auf Euch verlassen können!", sourceObjectiveStatus = "unverified-source-field" }
quests[66547] = { id = 66547, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das alles gehört in ein Museum... irgendwann einmal.", description = "Wellen der Titanenverteidigung, entkommene Protodrachen, Schlüssel, die einen in Konstrukte verwandeln... Ich muss schon sagen.\n\nIch hatte mein ganzes LEBEN noch nie so viel Spaß!\n\nObgleich Naleidea wahrscheinlich behaupten wird, dass jetzt erst der eigentliche Spaß beginnt. Wir sitzen auf einer Fundgrube vertraulicher Titanendaten, und das alles dank Eurer Bemühungen!\n\nKommt zu uns ins Lager, sobald Ihr könnt, dann vergleichen wir unsere Notizen.", sourceObjective = "Trefft Toddy im Lager der Drachenschuppenexpedition.", progress = "Nochmals Danke für das einmalige Erlebnis!", completion = "Unsere Hinweise sind vorerst versiegt. Zumindest, bis wir mehr Informationen aus diesen Scheiben herausholen können.\n\nBleibt bis dahin aufmerksam und folgt den vorhandenen Hinweisen: Man weiß nie, woher das nächste Abenteuer kommen wird!", sourceObjectiveStatus = "unverified-source-field" }
quests[66549] = { id = 66549, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rennen der Küste des Erwachens", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren." }
quests[66551] = { id = 66551, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die schrecklichen Drei", sourceObjective = "Besiegt Haniko in einem Haustierkampf", sourceObjectiveStatus = "unverified-source-field" }
quests[66553] = { id = 66553, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aushöhlung", description = "Die Winterpelze sind ganze besondere Furbolgs.\n\nIch würde sie als ein bisschen \"eigenbrötlerisch\" einstufen. Sie sind wie Geister aus dem Untergrund, ihre Pelze lassen sich im Schnee kaum ausmachen.\n\nFrüher blieben sie unter sich, aber jetzt sind sie so richtig aggressiv. Sie haben unser Lager ohne jede Provokation angegriffen!\n\nIrgendwas stimmt nicht, sonst hätten sie das nicht getan. Ich kann sie ja nicht fragen, was los ist... noch nicht, aber vielleicht könnt Ihr in ihrem Dorf nach Hinweisen suchen?", sourceObjective = "Findet 6 Hinweise in der Winterpelzhöhle.", completion = "Was habt Ihr gefunden?", sourceObjectiveStatus = "unverified-source-field" }
quests[66554] = { id = 66554, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aggressive Selbstverteidigung", description = "Bei dem Aufruhr, in dem die Winterpelze sich befinden, wird es ihnen wahrscheinlich nicht besonders gefallen, wenn Ihr Euch da oben ein wenig umseht.\n\nScheut nicht davor zurück, Euch zu verteidigen, wenn sie es darauf anlegen. Eine entschiedene Erinnerung, dass Ihr für so etwas nicht zu haben seid, könnte ihnen vielleicht wieder etwas Vernunft einbläuen.\n\nVersucht aber, niemanden zu töten, okay? Ich weiß, wie das manchmal mit Euch Abenteurern so ist.", sourceObjective = "Tötet 6 Winterpelzfurbolgs.", completion = "Hoffentlich wart Ihr nicht zu hart zu ihnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66555] = { id = 66555, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Moment der Geduld", description = "Aye, klingt nach einem echten Chaos da oben. Als wäre da ein Sturm durch, der alles auseinandergenommen hat. Ich kann schon verstehen, warum sie so aufgebracht sind, aber warum greifen sie deshalb uns an?\n\nEs wäre deutlich einfacher, wenn wir das einfach ausdiskutieren könnten, aber die Winterpelze sind besonders schweigsam und sprechen anscheinend kein gewöhnliches Furbolgisch. Furbolgianisch? Ach, Ihr wisst schon.\n\nIch vermute mal, dass Ihr es nicht geschafft habt, Euch während Eures Besuchs mit einem von denen zu unterhalten, oder?", sourceObjective = "Helft bei Sonovas Übersetzung.", completion = "Dann übersetzen wir dieses Chaos mal...", sourceObjectiveStatus = "unverified-source-field" }
quests[66556] = { id = 66556, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eishöhle in Sicht", description = "Nun, Euer Akzent ist fürchterlich und zehntausend Jahre der Isolation und der linguistischen Drift helfen da auch nicht... aber ich glaube, zumindest einen groben Eindruck bekommen zu haben.\n\nDer gemeinsame Nenner dessen, was sie versucht haben zu sagen, war etwas über einen \"schlechten Höhlenwind\" oder eine \"böse Sturmhöhle\". Entweder das, oder ihre Wäsche war zu Donnerstag?\n\nNun, das ist nicht so, als würde man Gnomisch lernen. Es wird einige Stolpersteine geben. Bei der Höhle bin ich mir allerdings ziemlich sicher, also lasst uns dort anfangen.", sourceObjective = "Untersucht die Höhle.", progress = "Besser krieg ich das nicht hin. Könnt es ja selbst versuchen, wenn es Euch nicht gefällt.", completion = "Ich hab Euch doch gesagt, ich hatte recht mit der Höhle. Mal sehen, ob wir ein paar ordentliche diplomatische Beziehungen knüpfen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[66557] = { id = 66557, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Akademische Bekanntschaften", description = "Aye, diese Winterpelzvariante der Furbolgsprache stellt sich als ziemlich harte Nuss heraus, selbst für mich.\n\nIch hab ein paar Kollegen im Lager im Nirgendwo, die vielleicht helfen können. Ich hab gehört, dass es noch andere Furbolgstämme in der Umgebung gibt. Vielleicht hilft es, unsere Aufzeichnungen zu den verschiedenen Dialekten miteinander zu vergleichen.", sourceObjective = "Findet einen weiteren Experten in Furbolgsprachen im Lager im Nirgendwo.", completion = "Ich spreche mein eigene Sprache, ja. Aber erst brauche ich Eure Hilfe bei einer Sache.", sourceObjectiveStatus = "unverified-source-field" }
quests[66558] = { id = 66558, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rowie", description = "Ihr wart es doch, <der/die> mit den anderen aus Brackenfell zurückgekehrt ist, nicht wahr? Dann wisst Ihr vermutlich, was mit Kaqiata passiert ist...\n\nIhr Sohn Rowie ist völlig verstört, seit Brena und die anderen ohne sie zurückgekehrt sind. Ich bleibe hier, falls er zurückkehrt, aber könntet Ihr vielleicht nach ihm suchen?\n\nIch glaube, dass er in Richtung Osten zur Eishöhle fortgelaufen ist. Er hat etwas davon erzählt, dass er da drin einen Yeti bekämpfen will!", sourceObjective = "Findet Rowie.", progress = "Ich muss mich beweisen!", completion = "Danke, dass Ihr mir geholfen habt. Ihr seid nett.", sourceObjectiveStatus = "unverified-source-field" }
quests[66559] = { id = 66559, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zum Lager", description = "Ich habe Mordigan wie einen besessenen Zwerg da rausrennen sehen. Ich gehe ihm hinterher und stelle sicher, dass er in einem Stück zurückkommt.\n\nWenn Ihr entlang der Klippe geht und die Wasserfälle hinunterspringt, solltet Ihr es vermeiden können, noch mehr Gorlocs aufzuscheuchen.\n\nWir sehen uns im Lager.", sourceObjective = "Kehrt zu Prüfer Rowe in Walfängerwinkel zurück.", completion = "Es scheint, Ihr habt unseren Zwerg zurückbringen können. Und unversehrt noch dazu. Ich danke Euch im Namen unseres Teams und der Drachenschuppenexpedition.\n\nWir werden Mordigan aufpäppeln und dann alles hier zusammenpacken.\n\nAuf diesen Hügeln gibt es nichts außer Blut und Salt.", sourceObjectiveStatus = "unverified-source-field" }
quests[66575] = { id = 66575, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegenstand als Auftragsgeber: Phiole", description = "<Diese merkwürdige Phiole, die zwischen dem Kleinkram im Tarasekversteck lag, scheint mit einer dickflüssigen, blubbernden Flüssigkeit gefüllt zu sein.>\n\n<Es wäre klug, sie Alvi zu zeigen.>", sourceObjective = "Bringt den Gegenstand zu Wegbehüterin Alvi.", sourceObjectiveStatus = "unverified-source-field" }
quests[66577] = { id = 66577, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einladung der Aspekte", sourceObjective = "Sprecht mit Furorion, um etwas über die Ratsversammlung zu erfahren.", completion = "Ich kann es kaum erwarten, die Dracheninseln mit Euch zu sehen, {name}!\n\nAlso dann, ich glaube, diese winzige Verbündete von Euch sagte etwas über den Aufbau einer Expedition.", sourceObjectiveStatus = "unverified-source-field" }
quests[66578] = { id = 66578, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A > B Reward Test (Low Health)" }
quests[66579] = { id = 66579, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geräusche der Heilung", description = "<Ihr hört, wie ein sanftes Geräusch aus der leise summenden Scheibe erklingt.\n\nOlea Manu weiß vielleicht mehr darüber.>", sourceObjective = "Bringt die resonierende Scheibe zu Olea Manu in der Rast des Glaubens.\n\nBereitgestellter Gegenstand:", completion = "Den Kerkermeister gibt es nicht mehr. Was Ihr bringt, ist der Beweis. Zereth Mortis beginnt, sich selbst zu heilen! Vielleicht findet Ihr neue Werkzeuge, die aus dieser Heilung hervorgehen. Werkzeuge, die eine starke Resonanz mit den Chiffren aufweisen. Mit ihnen könnt Ihr uns von den verbliebenen Schlundgebundenen befreien.", sourceObjectiveStatus = "unverified-source-field" }
quests[66582] = { id = 66582, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Energiegewinnung", description = "Normalerweise ist das Sammeln von Energie unproblematisch. Doch die Energie, die wir benötigen, ist gewaltig und instabil. Dieses verzauberte Gefäß sollte als sicheres Transportmittel dienen.\n\nIm Südwesten gibt es ein Gebiet, in dem es vor energiegeladenen Kreaturen nur so wimmelt. Die anomale Energie dieser Kreaturen ist mächtig, aber instabil.\n\nSammelt ihre Energie und kehrt zu mir zurück. Dann brechen wir gemeinsam zur restlichen Reise auf.", sourceObjective = "Sammelt Energie in dem Gefäß für Warpwirkerin Delandra im Lager Antonidas.", progress = "Habt Ihr gesammelt, was wir besprochen haben?", completion = "Du liebe Güte... Die Wärme in diesem Gefäß ist faszinierend.", sourceObjectiveStatus = "unverified-source-field" }
quests[66584] = { id = 66584, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zusätzliche Portalenergie", sourceObjective = "Ihr erlernt:", sourceObjectiveStatus = "unverified-source-field" }
quests[66586] = { id = 66586, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vermächtnis von Tyr: Geheimnisse der Vergangenheit", description = "Damit Raszageth die anderen Inkarnationen nicht befreien kann, müssen wir die Macht der Aspekte wiederherstellen.\n\nDoch das wird nicht einfach werden. Die Titanen schweigen und Hüter Tyr ist schon lange tot.\n\nKönigin Alexstrasza hat jedoch einen Plan. Im Ödland liegt eine Titanenanlage namens Uldaman. Sie glaubt, Tyrs Gefährten hätten eine Scheibe mit seinen Erinnerungen in den Tiefen der Anlage verborgen.\n\nBegebt Euch mit Euren Verbündeten nach Uldaman und findet die Scheibe für die Drachenkönigin. Wollen wir hoffen, dass wir den Aspekten mit Tyrs Wissen erneut zu Macht verhelfen können.", sourceObjective = "Geht nach Uldaman im Ödland. Macht den Grund für die Erschütterungen ausfindig.", completion = "Ewige Drachen? Die haben schon immer Ärger gemacht.\n\nIch werde die Drachenkönigin darüber informieren, dass sie die Macht der Aspekte auf andere Weise wiederherstellen muss.", sourceObjectiveStatus = "unverified-source-field" }
quests[66588] = { id = 66588, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flunk der Ältere", sourceObjective = "Besiegt Flunk in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[66589] = { id = 66589, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Expeditionskoordination", description = "Mein Name ist Toddy. Ich trommle unseren Trupp von fröhlichen Abenteurern unter dem Banner der Drachenschuppenexpedition zusammen. Wir reden später über die Details. Im Moment sollten wir uns darauf konzentrieren, die Mannschaft zu versammeln.\n\nJede Expedition, die was auf sich hält, hat abwechslungsreiche Mitglieder. Wir brauchen Gelehrte, Handwerker und natürlich Forscher.\n\nAlso? Was steht Ihr hier noch rum? Stellt die Mannschaft zusammen!", sourceObjective = "Rekrutiert Forscher, Handwerker und Gelehrte in ganz Sturmwind für die Expedition zu den Dracheninseln.", progress = "Alle bereit zum Aufbruch?", completion = "Das war schnell!\n\nKönnt es wohl kaum erwarten, die Dracheninseln zu sehen, was? Geht mir genauso!", sourceObjectiveStatus = "unverified-source-field" }
quests[66595] = { id = 66595, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlummernde Entdeckung", description = "<Fragt Euch nicht, wie dieses merkwürdige Pergament in Eurer Tasche gelandet ist. Wichtig ist der Inhalt der Nachricht.>\n\nMitglieder der Drachenschuppenexpedition:\n\nEure Unterstützung ist gefragt! Meldet Euch sofort beim Außenposten der Rubinschuppen!\n\n<Bevor die Unterschrift erkennbar wird, verschwindet die magische Schrift der Notiz auch schon wieder in einer Wolke weiß-bläulichen Staubs und hinterlässt dabei ein leeres Papier und einen angenehm blumigen Duft.>", sourceObjective = "Bringt die Nachricht zu Thaelin Schwarzamboss im Außenposten der Rubinschuppen an der Küste des Erwachens.", completion = "Nachricht? Welche Nachricht?\n\nWas meint Ihr damit, sie wäre auf mysteriöse Weise verschwunden?\n\nAch, wie auch immer. Wir haben viel zu besprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66596] = { id = 66596, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flüstern in den Winden", sourceObjective = "Sprecht mit Erzmagier Khadgar in Sturmwind.", progress = "Unsere Reise beginnt mit Euch.", completion = "Eure Reaktion ist verständlich. Mir ging es genauso.", sourceObjectiveStatus = "unverified-source-field" }
quests[66597] = { id = 66597, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der alte Stein", description = "Dieser Stein hinter mir ist nur ein Teil von... wie nennt Ihr das... uralter Technologie, über die wir hier auf den Inseln gestolpert sind.\n\nAber wir sind noch nicht ganz sicher, was genau es ist. Wirklich verblüffend.\n\nWir haben einigen Freunden eine Nachricht geschickt, ob sie vielleicht helfen können. In der Zwischenzeit könnt Ihr vielleicht rausfinden, wie man das benutzt?", sourceObjective = "Untersucht den gravierten uralten Monolithen.", progress = "Also. Kommt da noch was oder ist das wirklich nur ein großer Haufen Steine?", completion = "Was für ein Symbol? Das kann nicht stimmen...\n\n<Thaelin kratzt sich den Bart.>\n\nEs gibt nur einen Weg, es herauszufinden...", sourceObjectiveStatus = "unverified-source-field" }
quests[66598] = { id = 66598, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fachwissen der Nachtgeborenen", description = "Uralte Symbole sind nicht wirklich mein Ding. Aber...\n\n<Thaelin durchsucht seine Taschen und holt schließlich eine Karte hervor. Am Anfang des Pergaments steht der Name Antonidas in großer, schlampiger Schrift.>\n\nAha! Hier ist es!\n\nEin kleiner Marsch, aber einige dieser alten Magienutzer findet Ihr... hier.\n\n<Er deutet auf einen Punkt auf der Karte.>\n\nVielleicht haben die Euch was anzubieten.", sourceObjective = "Findet Warpwirkerin Delandra im Lager Antonidas im Azurblauen Gebirge.", completion = "Weit gereist, wie ich sehe. Diese Symbole, von denen Ihr sprecht, sind in der Tat mysteriös und sehr alt.\n\nDa Ihr interessiert genug seid, um den ganzen Weg hierher zu reisen, um mich zu finden, ist ein wenig Führung das Mindeste, was ich Euch geben kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[66611] = { id = 66611, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saubere Luft", description = "Könnt Ihr das hören? Insekten! Überall. Und einige von denen sind ziemlich groß.\n\nWarum nutzt Ihr und Euer gleitender Freund nicht den thermischen Aufwind hinter mir, um etwas dagegen zu unternehmen?", sourceObjective = "Tötet 50 Insekten.", sourceObjectiveStatus = "unverified-source-field" }
quests[66612] = { id = 66612, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dilemma der Krabbenhüterin", description = "Die Krabben sind in Gefahr!\n\nUnd diese hier hatten eine wirklich harte Zeit. Ihr vorheriger Lebensraum wurde von den Primalisten überrannt und ich führte sie an diesen Ort, wo sie von Gorlocs angegriffen werden!\n\nIch dachte, dass sie hier sicher sein würden, aber die Gorlocs nähren nur die Aggressivität der Krabben und bescheren ihnen so ein frühzeitiges Ableben.\n\nBitte beseitigt einige Gorlocs und helft den Krabben bei der Flucht!", sourceObjective = "Tötet 12 Gorlocs im Klippensturzlager.", completion = "Die Aspekte mögen Euch segnen, {name}! Ihr habt meine lieben Krabben gerettet! Diesmal werde ich besser auf sie achten. Kein Gorloc wird meine Lieblinge je wieder überrumpeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[66614] = { id = 66614, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valinor, das Licht der Äonen" }
quests[66615] = { id = 66615, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nurgash Schlammborn" }
quests[66616] = { id = 66616, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oranomonos die Immersprießende" }
quests[66617] = { id = 66617, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mortanis" }
quests[66618] = { id = 66618, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mor'geth" }
quests[66619] = { id = 66619, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Antros" }
quests[66620] = { id = 66620, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smaragdbeschwörungen", description = "Merithra, die aktuelle Anführerin der grünen Drachen, hat darum gebeten, dass Ihr Euch in den Smaragdgärten mit ihr trefft.\n\nDrakonide Abgesandte des azurblauen Schwarms sind gekommen, um mehr über die Gärten zu erfahren. Da mit den blauen Drachen nicht immer alles friedlich verlief, ist es wichtig, dass die Beziehungen herzlich und positiv bleiben.\n\nIhr findet sie in ihrem Horst über der Schattenzuflucht in den Smaragdgärten, Merithras Wacht.", sourceObjective = "Sprecht mit Merithra bei Merithras Wacht auf den Ebenen von Ohn'ahra.", completion = "Habt Dank für Euer Kommen, {name}. Meine Gäste möchten die Smaragdgärten sehen und ich freue mich, sie zu empfangen.\n\nSollen wir anfangen?", sourceObjectiveStatus = "unverified-source-field" }
quests[66622] = { id = 66622, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entlaufene Werkzeuge", description = "Das ist ja furchtbar! Meine *hicks* Werkzeuge sind scheinbar weggerannt, als ich nicht aufgepasst habe. Ich will gar *hicks* nicht daran denken, dass sie ganz allein da draußen sind, total *hicks* verängstigt!\n\nKönntet Ihr sie für mich einsammeln? Seid einfach geduldig und *hicks* versucht, sie zu beruhigen, dann werden sie sich für *hicks* Euch bestimmt erwärmen!", sourceObjective = "Rettet 6 entlaufene Werkzeuge.", completion = "Habt Dank, {name}! Ich werde *hicks* Euren Heldenmut nie vergessen!", sourceObjectiveStatus = "unverified-source-field" }
quests[66633] = { id = 66633, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eindruck machen", description = "Diese Djaradin glauben, dass der schwarze Drachenschwarm erledigt ist. Sie fürchten oder respektieren Furorions Autorität nicht.\n\nWir müssen eine Ansage machen, um sie daran zu erinnern, dass der Obsidianschwarm zurück und stärker als je zuvor ist.\n\nTötet die Djaradin und markiert jeden Leichnam, damit sie auch ja nicht vergessen, wer hier regiert.", sourceObjective = "Rammt ein Banner der schwarzen Drachen in die Leichname von 12 Djaradin.", completion = "Ausgezeichnete Arbeit, {name}. So hinterlässt man eine Botschaft.", sourceObjectiveStatus = "unverified-source-field" }
quests[66635] = { id = 66635, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wieder wiedervereint", description = "Das sollte genügen. Ich kann die anderen am Rand des Hains spüren, bereit, den Traum zu betreten.\n\nSagt mir Bescheid, wenn Ihr so weit seid, und ich werde die Eiswände zerbersten lassen und die Kuppel einreißen. Hoffentlich werden meine Änderungen den Schwarm nicht entmutigen.\n\nDie Arbeit ist damit zwar noch lange nicht getan, aber immerhin werden wir dann wieder alle zusammen sein.", sourceObjective = "Sprecht mit Ysera, damit sie die Barriere senkt.", completion = "Ich fasse es nicht. Alles, was ich zu hoffen wagte...\n\nSie ist hier.\n\nAber sie hat sich verändert. Ich weiß nicht, was das bedeutet, und ich fürchte, wir haben nicht viel Zeit, um darüber nachzusinnen. Wir müssen Rymek folgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66636] = { id = 66636, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die andere Seite", description = "Wir haben endlich rausgekriegt, wo der dritte Stein hingehört. Tut Ihr mir den Gefallen? Ich habe den Stein am Rest des Behüterstabes angebracht. Klettert einfach auf das Gerüst, haltet ihn hoch und genießt die Vorstellung!", sourceObjective = "Öffnet die Tür mit dem Stab des Behüters.", completion = "Es gibt so viel zu sehen, und wir fangen gerade erst an!", sourceObjectiveStatus = "unverified-source-field" }
quests[66646] = { id = 66646, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kausalitäten unter Kontrolle bringen", description = "Die Ewigen haben die Zeitenergien zur Aggressivität gezwungen. Das ist nicht gut.\n\nBitte tötet alle Zeitelementare, die Ihr seht, während Ihr Botschafterin Chronormu helft. Ich bleibe hier und helfe ihr dabei, Eternus zu halten.", sourceObjective = "Tötet die Zeitelementare.", progress = "Konnte jemand von ihnen in die Vergangenheit flüchten? Würden wir das überhaupt merken? Hmmm.", completion = "Ausgezeichnete Arbeit! Normalerweise halte ich nichts davon, Zeit totzuschlagen, aber heute ist eine Ausnahme.", sourceObjectiveStatus = "unverified-source-field" }
quests[66647] = { id = 66647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn Elementare den Fokus verlieren", description = "Kalecgos und ich sind in den Lüften über dem Berg unter schwerem Beschuss. Die Primalisten sind unerbittlich und ihre Armee ist endlos.\n\nSchon bald könnten Kalecgos und ich von ihren Truppen überrannt werden.\n\nAber ich habe einen Plan.\n\nAm Fuß des Berges befindet sich eine Orcin namens Ruvin Steinzermalmer. Die Kirin Tor haben sie schon unzählige Male bekämpft.\n\nSie hat ein Gerät, das elementare Energien absorbieren und umlenken kann.\n\nNehmt es ihr ab und trefft mich anschließend weiter drinnen.", sourceObjective = "Holt den Elementarfokus zurück.", progress = "Der Elementarfokus sollte sich als nützlich erweisen, wenn Ihr ihn zurückholen könnt.", completion = "Das ist er! Seht zu , dass Ihr ihn behaltet... Ihr werdet ihn noch brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66648] = { id = 66648, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jenseits des Schicksals", description = "<Die Realität dreht sich um Euch. Eure Erinnerungen an diesen Ort verschwimmen und verschieben sich mit jedem Augenblick mehr. Irgendetwas hat sich verändert.>\n\n<Ihr seid Euch sicher, dass dies trotz aller Ähnlichkeiten nicht der Ort ist, den Ihr einst kanntet. Nicht ganz.>\n\n<Aber dennoch ruft der vor Euch liegende Weg. Weder Täuschung noch Verzerrung werden Euer Schicksal aufhalten.>", sourceObjective = "Besiegt 30 verschiedene Bosse schicksalhafter Schlachtzüge.", sourceObjectiveStatus = "unverified-source-field" }
quests[66649] = { id = 66649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Blatt wenden", description = "<Im Laufe der vielen Prüfungen spürt Ihr, wie die Kraft in Euch wächst. Was auch immer die Quelle dieser Anomalien ist, sie ersetzen Eure Verwirrung immer mehr durch Sicherheit.>\n\n<Taucht noch einmal in die Ungewissheit ein, kämpft gegen die Dunkelheit und ergreift das Schicksal mit beiden Händen.>", sourceObjective = "Besiegt 15 verschiedene Bosse schicksalhafter Schlachtzüge.", sourceObjectiveStatus = "unverified-source-field" }
quests[66650] = { id = 66650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finale des Schicksals", description = "<Ihr seid ganz ruhig. Die Natur dieser Erfahrung bleibt unergründlich, aber sie fühlt sich nicht mehr ungewohnt an. Ihr beherrscht jetzt diese Herausforderungen, und die Klarheit ist Eure letzte Belohnung.>\n\n<Mit klarem Verstand und ruhiger Hand schreitet Ihr ein letztes Mal voran. Gestaltet Euer eigenes Schicksal und seht, wie es sich vor Euch entfaltet.>", sourceObjective = "Besiegt 5 verschiedene Bosse schicksalhafter Schlachtzüge.", sourceObjectiveStatus = "unverified-source-field" }
quests[66651] = { id = 66651, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdächtige Klangeschäfte", description = "Die Klans Nokhud und Ukhel haben die Ewigen Kurgane eingenommen. Dahinter kann nur eine boshafte Absicht stecken. Unsere ehrwürdigen Vorfahren ruhen dort.\n\nIch habe unseren Initianden Zorig zu Nachforschungszwecken entsandt. Er ist bisher nicht zurückgekehrt.\n\nEs mangelt ihm an Selbstvertrauen, auch wenn er fähig ist. Bitte helft ihm, diesem unheilvollen Treiben ein Ende zu setzen!", sourceObjective = "Trefft Initiand Zorig in den Ewigen Kurganen.", completion = "Klan Ukhel entehrt sich mit dunkler Magie. Jetzt hat er sich mit seinen Nokhudverbündeten in die Kurgane begeben. Keiner der Klans sollte hier sein! Ich habe sie von hier aus beobachtet, wo sie mich nicht sehen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[66652] = { id = 66652, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück an den Heiler", description = "Ich erkenne von hier aus nicht, was sie tun, aber ich fürchte, sie entweihen die Kurgane.\n\nBitte begebt Euch zum nächsten Grab und versucht, ihr Ritual zu vereiteln.\n\nUnd wenn Ihr irgendwas findet, das erklärt, warum sie es durchführen, so bringt es mir bitte.", sourceObjective = "Untersucht das Ritual der Ukhel auf dem Grabhügel in der Nähe.", progress = "Habt Ihr das Ritual unterbrechen können? Irgendwelche Hinweise darauf, warum es dabei ging?", completion = "Dieser Speer... gehörte meiner Mutter, Cathan. Sie war eine großartige Jägerin. Als sie krank wurde, konnte ich... sie nicht retten.\n\nWie alle großen Zentauren der Maruuk wurde sie mit ihrer Waffe begraben. Aber das heißt ja, dass die Ukhel diese Waffen benutzen, um Geister herbeizurufen und sie in ihre Dienste zu zwingen... auch meine Mutter!", sourceObjectiveStatus = "unverified-source-field" }
quests[66654] = { id = 66654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schändervernichtung", description = "Meine Mutter war eine Heldin. Sie verdient Frieden und Ruhe, nicht diese... Versklavung! Das verdient keiner unserer Helden.\n\nSie müssen dafür bezahlen. Und unsere Vorfahren müssen wieder mit ihren Waffen ruhen, ehrenvoll. Holt die Waffen von diesen Grabschändern zurück!", sourceObjective = "Tötet Schänder der Nokhud und Grabstörer der Ukhel und erobert die Ahnenwaffen zurück, die sie gestohlen haben.", progress = "Habt Ihr die Waffen von den Grabräubern zurückgeholt?", completion = "Das ist ein guter Anfang. Mit diesen Waffen kann ich ihre Besitzer befreien... hoffentlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[66655] = { id = 66655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reagenzien zur Ent-Nekromantierung", description = "Ich fürchte, die Geister werden ihre Gräber nicht wiederfinden, selbst wenn wir sie aus den Klauen der Ukhel befreien.\n\nDie Ukhel zwingen selbst deren Tierbegleiter, die sie ihr Leben lang begleitet und beschützt haben, zurück ins Leben.\n\nBringt mir die Schädel dieser Tiere und die heilige Erde, die von diesen Ungeheuern entweiht wurde. Zusammen sollten diese Reagenzien dafür sorgen, dass unsere Vorfahren endlich Frieden finden.", sourceObjective = "Sammelt 4 intakte Schädel von auferstandenen Gefährten und 6 Klumpen heiliger Erde.", progress = "Habt Ihr die Reagenzien? Wir müssen die Ahnen befreien, bevor Klan Ukhel sie aus den Kurganen wegschafft.", completion = "Perfekt! Mit denen kann ich sie aus den Klauen der Ukhel befreien. Auf dass sie wieder in Frieden ruhen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[66656] = { id = 66656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Definitiv letzte Ruhe", description = "Die Ahnen sind von dieser dunklen Magie gepackt. Sie werden kämpfen, statt zu folgen. Die Ukhel haben unsere stärksten Krieger und Jäger erweckt. Es wird nicht leicht, sie aufzuhalten.\n\nIch komme mit und helfe Euch. Es wird Zeit, den Speer meiner Mutter wieder in die Schlacht zu führen.\n\nIch habe ein Totem hergestellt, das den unterworfenen Geistern dabei hilft, zurück in ihre Kurgane zu finden. Verwendet es, sobald Ihr sie bezwungen habt.", sourceObjective = "Besiegt jeden der ruhmreichen Zentaurengeister und benutzt dann Zorigs Totem der Erholung, um sie zu befreien.", progress = "Beeilt Euch. Wir müssen diese Geister befreien.", completion = "Ich bin so erleichtert, dass meine Mutter wieder ihren Frieden gefunden hat. Habt Dank, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[66657] = { id = 66657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Und bleibt tot!", description = "Grabrufer Arban hat sich im größten Grabhügel verschanzt. Dort ruhen die ersten Vorfahren der Maruuk. Verhindert, dass er Maruuk und Teera erweckt!", sourceObjective = "Betretet das größte Hügelgrab und bezwingt Grabrufer Arban.", progress = "Wenn dies getan ist, wird es kein Grab für ihn geben.", completion = "Im Gegensatz zu meiner Mutter und unseren Ahnen ist um Arban nicht schade. Danke, dass Ihr mir geholfen habt, sie zu rächen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66658] = { id = 66658, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Angriff der Nokhud: Wiederholen ist gestohlen", description = "Die Waffen von Teera und Maruuk wurden entwendet, bevor wir Grabrufer Arban aufgehalten haben. Unsere größten Vorfahren könnten erneut auf diesen Ebenen kämpfen... für die Nokhud.\n\nBegebt Euch zum Angriff der Nokhud. Findet Maruuk und Teera. Wenn Ihr sie bezwungen habt, bringt ihre Waffen zum Grabhügel von Teerakai zurück. Wir werden sie an einem Ort, der sich leichter schützen lässt, mit der ihnen gebührenden Ehre wieder zur Ruhe betten.", sourceObjective = "Begebt Euch zum Angriff der Nokhud, besiegt Teera und Maruuk und platziert ihre Waffen im Kurgan von Teerakai.", progress = "Konntet Ihr die legendären Geister unserer Gründer besiegen?", completion = "Ich hätte nie gedacht, von einem Außenseiter so viel Hilfe zu bekommen. Ihr habt meinen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[66660] = { id = 66660, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf die Plätze, fertig...", description = "<Nozdormus sieht sich mit unstetem Blick um.>\n\nJe tiefer sie fallen, desto schneller bewegen sie sich. Sie reißen Löcher in das Gewebe der Zeit und schlagen große Wellen. Ihr werdet schnell sein müssen, um sie zu fassen.\n\n<Nozdormus Fokus wird schärfer und richtet sich auf Euch.>\n\nIch werde meine Zeitwanderer entsenden, um Euch dabei zu helfen, über die Pfade der Zeit zu navigieren und Eure Bemühungen zu beschleunigen. Vermeidet es, Euch mit den temporalen Einheimischen abzugeben, und hört nicht auf, bis Ihr Chronormu gefunden habt!\n\nGeht. Uns bleibt nicht viel Zeit.", sourceObjective = "Schließt Euch Andantenormu und Siaszerathel in der Vergangenheit an.", completion = "Seid Ihr bereit, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[66661] = { id = 66661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das ist nur eine Münze, was soll die wert sein?", description = "<Dieser kuriose Gegenstand bietet mehr Fragen als Antworten. Wie seid Ihr in den Besitz dieses Gegenstands gekommen? Wofür wird er verwendet? Ist er gefährlich?>\n\n<Wenn die Ewige Stadt keine Antworten für Euch bereithält, dann sicherlich die Mittler, die dort ihren Geschäften nachgehen.>", sourceObjective = "Wendet Euch an einen Mittler in Oribos, um mehr zu erfahren.", completion = "Diese Münze... Niemand in Oribos wird sie annehmen. Und ich bezweifle, dass Ihr die Reise zu dem Markt, wo sie gehandelt wird, überleben würdet. Wenn ich einen Vorschlag machen darf... Vielleicht könnten meine Partner und ich Euch helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[66671] = { id = 66671, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pfad ins Nirgendwo", description = "Ihr seht wie <ein gewillter und fähiger Abenteurer/eine gewillte und fähige Abenteurerin> aus! Wie würde es Euch gefallen, der Drachenschuppenexpedition auszuhelfen?\n\nWir haben ein nettes kleines Lager mitten in der Wildnis errichtet.\n\nEs gäbe dort einiges für Euch zu tun, vorausgesetzt, Ihr wollt den Weg dorthin auf Euch nehmen.\n\nSprecht mit meiner Schwester Maddi, wenn Ihr dort ankommt. Sie wird Euch einführen.", sourceObjective = "Trefft Maddi Streuschuss im Lager im Nirgendwo im Azurblauen Gebirge.", completion = "Caddi hat Euch geschickt? Sie war noch nicht hier, als all der Tumult wegen der Tuskarr und der Furbolg ausbrach!\n\nEs wäre die Untertreibung der Woche, zu behaupten, es gäbe im Lager was zu tun. Wir ersaufen in Problemen!", sourceObjectiveStatus = "unverified-source-field" }
quests[66673] = { id = 66673, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprecht mit Koranos", description = "Die Wächter haben über die Jahre einiges beobachtet. Viele von ihnen sind den Launen der Zeit anheimgefallen, doch uns bleibt noch Koranos.", sourceObjective = "Sprecht mit Koranos in Valdrakken.", completion = "Die Splitterflammen werden uns diese Steine nicht kampflos überlassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66675] = { id = 66675, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aspektmacht", description = "Der Mutterschwurstein ist ein uraltes Geschenk der Titanen an unsere Schwärme. Wenn unsere Informationen stimmen, können wir ihn reaktivieren und so unsere Aspektkräfte wiederherstellen.\n\nDer Erfolg mag ungewiss sein, aber wenn es auch nur eine kleine Chance gibt, muss ich es versuchen.\n\n{name}, ich würde mich freuen, wenn Ihr mir helfen würdet.", sourceObjective = "Helft Alexstrasza am Mutterschwurstein.", completion = "Was ist passiert, {name}? Wo ist Alexstrasza?", sourceObjectiveStatus = "unverified-source-field" }
quests[66676] = { id = 66676, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reinschleichen", sourceObjective = "Kehrt zu Radiya an den Quellen von Ohn'iri zurück.", completion = "Ihr seid zurück! Seht mal... Lizi wird bald wieder wohlauf sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[66679] = { id = 66679, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rubinlebensschrein-Schleife", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[66680] = { id = 66680, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riesenwildschäfchen zählen", description = "Wie frustrierend. Das stammt von einem tollwütigem Hirsch, dem mein Bruder Olekk und ich während unseres letzten Erkundungsgangs begegnet sind.\n\n<Watu deutet auf sein blutiges Bein und zuckt zusammen.>\n\nSeid Ihr hier, um zu helfen? Nach dem Angriff der Primalisten ist unsere Riesenwildschafherde in den Pinienwald geflüchtet. Dort sind die Tiere nun verstreut. Hier im Lager sind wir auf ihre Wolle und Milch angewiesen.\n\nNehmt diese Pfeife. Sie ist das Signal für Wunsch, die Riesenwildschafe zurückzubringen. Sondo der Metzger hat auch noch besondere Leckerlis, falls Wunsch etwas motiviert werden muss.", sourceObjective = "Freundet Euch mit Wunsch mithilfe von Essen an und benutzt Wunsches Pfeife, um 5 verirrte Riesenwildschafe im Weisenkronenpinienwald zu retten.", completion = "Unsere Riesenwildschafe haben überlebt? Da hat Wunsch sich aber ein paar ausgiebige Krauler am Bauch verdient. Kümmert Ihr Euch darum? Ich kann mich ja nicht bewegen. <Watu seufzt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[66681] = { id = 66681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewitter ziehen auf", description = "Wenn Ihr in den Pinienwald geht, dann erlegt doch bitte alle sturmberührten Tiere. Es fällt mir nicht leicht, Euch darum zu bitten, aber ihnen kann nicht geholfen werden. Sie leiden und verbreiten Aggressivität.\n\nIch schätze, dass es sich dabei um das Werk der Primalisten handelt. Das muss von ihrem Außenposten in der Nähe kommen. Ich habe dort einen seltsamen magischen Altar gesehen.\n\nIch werde mir das noch mal anschauen. Wenn ich nicht zurück sein sollte, wenn Ihr wieder da seid, kann Späher Watu Euch über ein paar weitere Aufgaben informieren. Wir sind für jede Hilfe dankbar.", sourceObjective = "Tötet 8 sturmberührte Tiere im Weisenkronenpinienwald.", completion = "Die Wälder sollten nun ein wenig sicherer sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[66683] = { id = 66683, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzweifelte Analyse", description = "<Watu murmelt mit geschlossenen Augen und verschränkten Armen vor sich hin.>\n\nNatürlich muss es ausgerechnet ein Hirsch sein, der mich aufspießt. Jetzt bin ich nur eine weitere Person, die Hilfe braucht. Mein Bruder heimst den ganzen Ruhm ein, und zu Hause wird das niemanden überraschen.\n\n<Watu blickt auf.> Was? Was habt Ihr da? Leuchtende Steine? Ja, ich kann mir einen davon anschauen, aber bringt den Rest zu jemand anderem. Ich bin Jäger, kein Archäologe. <Watu schnaubt und starrt auf sein Bein.> Vielleicht ist es ja Zeit für einen Karrierewechsel. Na los, Ihr habt Euch als nützlicher erwiesen als ich.", sourceObjective = "Stellt Nachforschungen über die sturmberührten Splitter im Nadelholzposten an.", progress = "<Auf Watus Gesicht spiegelt sich ein merkwürdiger Ausdruck wider. Er scheint Eure Anwesenheit kaum wahrzunehmen und dreht den Splitter in seinen Händen wie besessen hin und her.>\n\nSeht Ihr, wie er leuchtet? Wie zuckende Blitze.", completion = "<Watu schaut fassungslos auf sein Bein. Der Splitter hat sich tief in das Fleisch gebohrt und aus der Wunde strömt frisches Blut.>", sourceObjectiveStatus = "unverified-source-field" }
quests[66684] = { id = 66684, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmjäger", description = "<Watu reißt den Splitter raus und schnappt nach Luft.>\n\nIch... habe komplett die Kontrolle verloren. Olekk hatte recht. Diese schreckliche Magie muss das Werk der Primalisten sein. Haltet sie bitte auf!\n\nIch muss meinen Bruder zurück ins Lager bringen.", sourceObjective = "Vernichtet die Quelle der Sturmmagie der Primalisten.", completion = "Ihr seid zurückgekehrt! Ich konnte die Zerstörung der Quelle bis hierher spüren.", sourceObjectiveStatus = "unverified-source-field" }
quests[66687] = { id = 66687, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Land der Eliten", description = "Ihr solltet von Rellen dem Gelehrten wissen, der den Zentauren die Mittel gab, in einem gnadenlosen Land zu überleben. Seine Erinnerung erfordert Opfergaben von würdigen Tieren.\n\nGebt Acht, <Reisender/Reisende>, sie sind nicht so gefährlich, wie sie vor Äonen waren, doch sie sind immer noch die Eliteraubtiere dieser Ebenen.", sourceObjective = "Sammelt 10 Schattenspinnernetze, 2 Slyvernkrallen und 2 Donnerrückgratschuppen.", progress = "Seid Ihr mit den Opfergaben zurückgekommen?", completion = "Ihr seid wohlbehalten zurückgekehrt. Gut. Respektiert stets die Tapferkeit der Tiere.", sourceObjectiveStatus = "unverified-source-field" }
quests[66688] = { id = 66688, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeichen des Windes", description = "Als die Elemente, die wahren Urwesen dieser Welt, die Zentauren herausforderten, trat Himia dem Geschenk entgegen, das wir erhalten hatten: mit dem Wind.\n\nEin singender Stein ragt auf den Ebenen auf. Dort könnt Ihr Eure Gaben dem Wind darbieten, um ihre Erinnerung zu erwecken. Solche Gaben können überall um uns herum gefunden werden: eine Vogelfeder, ein Pflanzensamen, Flussschilf.", sourceObjective = "Sammelt Windgaben und legt sie in das Opfergefäß in der Nähe des singenden Steines.", progress = "Der singende Stein befindet sich nur einen kurzen Galopp von hier entfernt.", completion = "<In dem eisernen Behälter sind aschene Überreste früherer Windgaben zu sehen.>\n\n<Ihr legt das, was Ihr gesammelt habt, dazu.>", sourceObjectiveStatus = "unverified-source-field" }
quests[66689] = { id = 66689, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr als ein Stein", description = "<Die Splitter fühlen sich glatt und warm an. In ihrem Kern blitzt es.>\n\n<Vielleicht wissen Watu oder Olekk mehr darüber.>\n\n<Beim Gedanken daran, den Splitter aus der Hand zu geben, presst Ihr ihn instinktiv an Eure Brust. Ihr wollt ihn nie wieder loslassen.>", sourceObjective = "Zeigt die sturmberührten Splitter Watu.", completion = "<Watu nimmt Eure Anwesenheit nicht wahr. Er bleibt weiterhin sitzen, ohne das verletzte Bein zu belasten. Seine Augen sind geschlossen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[66690] = { id = 66690, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff der Nokhud: Der letzte Ahne", description = "Ihr habt bewiesen, dass Ihr uns <ein Verbündeter/eine Verbündete> seid und aufrichtiges Interesse an unseren Werten und unserer Lebensweise habt. Es gibt noch einen Vorfahren, von dem ich Euch gerne erzählen würde, aber es ist gefährlich.\n\nTötet den verräterischen Balakar, Anführer der Nokhud, niemandes Sohn. Sein wertvolles Medaillon legt er niemals ab. Bringt es mir und ich werde ewig in Eurer Schuld stehen.", sourceObjective = "Besiegt Balakar Khan und erbeutet das Medaillon der Ahnen beim Angriff der Nokhud.\n\nIhr könnt den Angriff der Nokhud allein betreten, wenn Ihr Euch über die Anhängerdungeons anmeldet.", progress = "Balakar trennt sich nie von seinem Medaillon. Ihr werdet ihn töten müssen.", completion = "Ich hätte nie gedacht, dass ich das einmal erleben würde.", sourceObjectiveStatus = "unverified-source-field" }
quests[66691] = { id = 66691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waking Shores - Race 01 - Intermediate", description = "Der Kurs hat einen ähnlichen Aufbau wie der vorherige, nur mit mehr Varianz bei der Platzierung der Kontrollpunkte.\n\nFalls Ihr steckenbleibt, betätigt die Pfeife, dann setze ich Euch zurück.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[66692] = { id = 66692, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rubinlebensschrein-Schleife - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[66693] = { id = 66693, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal herausfordern: Schloss Nathria" }
quests[66694] = { id = 66694, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal herausfordern: Sanktum der Herrschaft" }
quests[66695] = { id = 66695, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal herausfordern: Mausoleum der Ersten" }
quests[66696] = { id = 66696, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal herausfordern: Schicksal der Schattenlande" }
quests[66698] = { id = 66698, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riesenwildschafe zählen", description = "Eine unserer wichtigsten Ressourcen sind unsere Riesenwildschafe. Jeder Verlust wirkt sich deutlich auf die Stärke unseres Klans aus.\n\nEin paar der Riesenwildschafe sind davongelaufen und haben den Anschluss an die Herde verloren. Unsere Schäfer könnten bei der Rückführung der verlorenen Schafe Eure Hilfe brauchen.", sourceObjective = "Sprecht mit dem Hirten der Aylaag und führt die verlorenen Schafe zurück zum Klan.", completion = "Habt Dank. Unser Klan weiß Eure Hilfe sehr zu schätzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66699] = { id = 66699, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befragung der Einheimischen", description = "Kalecgos ist weise, den Rat der Tuskarr einzuholen. Sie haben Generationen an Erfahrung mit diesem Gebiet.\n\nViele rasten hier auf ihrem Weg zu den verschiedenen Lagern entlang des Gebirges.\n\nFragt herum! Einer von ihnen muss etwas über lokale Leylinien wissen.", sourceObjective = "Sprecht mit den Tuskarr im Lager Antonidas.", progress = "Ich würde Euch eine Schüssel anbieten, aber Ihr scheint in Eile.", completion = "Ich würde es an Eurer Stelle bei Brena versuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66700] = { id = 66700, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der schwarze Locus", description = "Er ist wirklich sehr faszinierend, nicht wahr? Der Locus war zu viel für die Splitterflammen. Aber er passt genau in meine Hände. Schon seltsam.\n\n<Adenedal schüttelt den Kopf.>\n\nVielleicht nicht. Nicht heute. Nicht mehr. Nehmt ihn mir ab. Er ist nicht meine Bürde.\n\nAuf Wiedersehen, <mein lieber Freund/meine liebe Freundin>.", sourceObjective = "Bringt den schwarzen Locus zu Telemantin Aerilyn.", progress = "Habt Ihr etwas, das Ihr mir zeigen möchtet?", completion = "Er wurde in den Ruinen von Nelthazan gefunden? Faszinierend. \n\nDie Muster darauf stammen aus alter Zeit, aber sie ähneln denen auf anderen Artefakten, die wir im Umfeld der Machenschaften von Todesschwinge entdeckt haben.\n\nDas muss weiter untersucht werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[66703] = { id = 66703, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schneeballeffekt", description = "Schneebalggnolle klug. Wissen, wenn Essen auf Eis machen, Essen länger haltbar. Aber nicht gewöhnliches Eis, nein. Magisches Eis viel besser!\n\nIst Werk von Schamanen. Und sie Frostbiss hiergelassen haben, um neben köstlichem Tuskarrfleisch zu verhungern.\n\nWenn {race} Tuskarr helfen will, nicht viel Zeit bleiben.\n\nAber Frostbiss weiß, wie Zauber brechen.\n\nWarum Frostbiss helfen? Mag Schamanen auch nicht.", sourceObjective = "Holt 3 Schneebalgtotems von den Schneebalgschamanen im Azurblauen Gebirge.", progress = "Tuskarrfreunde sehen nicht so gut aus, {race}.", completion = "Listige Schamanen also tot?", sourceObjectiveStatus = "unverified-source-field" }
quests[66704] = { id = 66704, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mugurlglrlgl!", description = "Mrglgulglrrlglgul! Grurguglullgurl!\n\nGruglrlgllrugl rrgulgrulgrgl grugll gurgull gur. Murgllgllrugl gurgllglrl Murgul gruggullgl. Murguglegurgllgur gurgll gurgulgul guruulgurllgr guuglrllgl.\n\nMgrgulllglll gurl gugll.\n\n<Ihr seid Euch nicht sicher, was genau er Euch sagen will, aber er gestikuliert wild, als würde er auf jemanden oder etwas einstechen. Dieser Murloc will wohl, dass Ihr etwas tötet.>", completion = "Lrgktrr O'Glrlrlrl!\n\n<Die Murlocs scheinen zufrieden zu sein.>" }
quests[66708] = { id = 66708, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reiter im Schnee", description = "Seid gegrüßt, {class}. Diese magische Kuppel ist wahrlich beeindruckend, nicht wahr? Doch obwohl sie uns vor der klirrenden Kälte und den Gefahren der Wildnis schützt, können wir uns nicht ewig auf die Kirin Tor verlassen.\n\nVor einigen Tagen sind einige unserer erfahrensten Jäger in die Wälder aufgebrochen, um nach Essen und Vorräten zu suchen, aber sie sind nicht zurückgekehrt. Ich weiß, ihr Anführer, der Alte Grimmhauer, ist ein erfahrener Wanderer und Jäger, aber wir können unsere Sorge um ihn und seinen Jagdtrupp nur schwer abstellen.\n\nKönnt Ihr sie für mich aufspüren?", sourceObjective = "Findet die vermissten Jäger der Tuskarr im Azurblauen Gebirge.", completion = "<Dieser Tuskarr liegt bewusstlos im Schnee und ein Holzspeer ragt aus seiner Seite.>", sourceObjectiveStatus = "unverified-source-field" }
quests[66709] = { id = 66709, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Einmaleins der Feldsanitäter", description = "<Schwer zu sagen, wie lange dieser verwundete Tuskarr schon alleine hier im Wald liegt, doch ohne Hilfe wird er nicht mehr lange durchhalten.>", sourceObjective = "Helft dem Alten Grimmhauer, sich von seinen Wunden zu erholen.", progress = "Natürlich, lasst Euch ruhig Zeit. Das können so Junglinge wie Ihr schließlich am besten.", completion = "Ernsthaft? Ich war sicher, Eure \"Hilfe\" würde mein Ende bedeuten.", sourceObjectiveStatus = "unverified-source-field" }
quests[66710] = { id = 66710, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blitzfrost-Überflug", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[66711] = { id = 66711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delikate Dunkelheit", description = "Aufgrund der Lebensweise unseres Klans sind manche Ressourcen knapp. Wir haben nicht die nötige Zeit, um dem Land seine Metallressourcen zu entreißen.\n\nDie verstorbene Khan hat viele Handelsverbindungen zu einer Reihe von Leuten aufgebaut, und ich habe vor, ihre Dienste auch weiterhin in Anspruch zu nehmen.\n\nIn der Bucht in der Nähe finden sich Eimer, in denen wir Flussschnecken fangen. Sie gelten bei einigen unserer Nachbarn als Delikatesse. Bringt mir welche davon, damit ich damit handeln kann.", sourceObjective = "Sammelt 12 Flussschnecken für Hadari.", progress = "Passt auf die Fallen auf. Sie könnten etwas aggressivere Ärgernisse beinhalten.", completion = "Ah, das ist sicher hilfreich.\n\nEs ist nicht leicht für mich, wegen so einer wichtigen Ressource auf Fremde angewiesen zu sein, aber mir fällt keine andere Lösung ein.", sourceObjectiveStatus = "unverified-source-field" }
quests[66712] = { id = 66712, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blitzfrost-Überflug - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[66715] = { id = 66715, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Extraktion", description = "Am wichtigsten ist es jetzt, meine Leute zurückzubringen. Vorzugsweise unverletzt.\n\nUnd so schwer es mir auch fällt, dies zuzugeben: Ich bin nicht in der Lage, allein zu kämpfen.\n\nWerdet Ihr uns helfen?", sourceObjective = "Rettet Tuskarr aus dem Schneebalglager im Azurblauen Gebirge.", completion = "Ihr nach Tod riechen... Frostbiss gefallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66718] = { id = 66718, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnolle müssen sterben" }
quests[66719] = { id = 66719, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einen Schritt zurück", description = "<Mein Freund/Meine Liebe>, mit großem Bedauern muss ich gestehen, dass ich mit der Plage vertraut bin, die Eure Art in diesen Ruinen heimsucht. Wenn Ihr weiter vordringt, werdet Ihr gewiss ihrem Wahnsinn anheimfallen.\n\nSei es durch Eure Erziehung oder Eure Natur... der Ruf, den Ihr vernehmt, ist psychologischer Art. Ihr verspürt ein Verlangen, das gestillt werden muss.\n\nEs beschämt mich zu sagen, dass ich die Mittel besitze, diese Verwünschung zu nähren. Es wird nicht dasselbe sein, aber Ihr werdet handlungsfähig bleiben... für den Moment.", sourceObjective = "Schützt Euch vor dem Ruf.", progress = "Ich bedaure, dass es so weit kommen musste.", completion = "Vielleicht sind unsere Völker gar nicht so unterschiedlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[66721] = { id = 66721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildreservat-Slalom", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[66722] = { id = 66722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildreservat-Slalom - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[66724] = { id = 66724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Leuchtfischerin", description = "Es tut mir leid, dass Ihr in diese Angelegenheit verwickelt worden seid, <Reisender/Reisende>.\n\nMein Bruder neigt dazu, zu... übertreiben. Dies ist nur die neueste seiner Narreteien, doch diese könnte ihn das Leben kosten.\n\nEr hört nicht auf mich. Er wird vermutlich auch nicht auf Euch hören.\n\nDoch es gibt jemanden, auf den er vielleicht hören würde: unsere Vorfahrin, Kauriq die Leuchtfischerin.\n\nBitte fangt ein paar Leuchtfische und bringt sie her. Mit ihnen werde ich versuchen, mit dem Geist von Kauriq zu sprechen, der in diesem Stein wohnt.", sourceObjective = "Besorgt 3 Leuchtfische und platziert sie im Gabenkorb.", progress = "Nicht all meine Ideen haben funktioniert, aber das hat nichts zu bedeuten!", completion = "Habt Ihr gut zugehört, Held?", sourceObjectiveStatus = "unverified-source-field" }
quests[66725] = { id = 66725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildreservat-Parcours", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[66726] = { id = 66726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildreservat-Parcours - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
