quests[66728] = { id = 66728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glutstrom-Flug - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[66729] = { id = 66729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abhängig von Bedingungen", description = "Ich mag die Allianz nicht. Erinnert Ihr Euch an mich?\n\nZieht los und tötet Schlundgebundene.", sourceObjective = "Tötet 1 Schlundgebundene.", sourceObjectiveStatus = "unverified-source-field" }
quests[66730] = { id = 66730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wahre Überlebende", description = "Ich weiß, dass wir ziemlich angeschlagen sind, doch wir dürfen nicht vergessen, warum wir hier sind. Unser Volk zählt auf uns, und ich habe nicht vor, es im Stich zu lassen. Wir müssen in dieser wilden Gegend einen vorübergehenden Platz für uns finden und ich weiß auch schon genau den richtigen Ort.\n\nUnd jetzt Schluss mit den Klagen und BEWEGUNG!", sourceObjective = "Findet den alten Grimmhauer am gefrorenen See im Azurblauen Gebirge und sprecht mit ihm.", completion = "War doch gar nicht so schwer, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[66732] = { id = 66732, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flusslauf des Hohen Blätterdachs", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[66733] = { id = 66733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flusslauf des Hohen Blätterdachs - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[66734] = { id = 66734, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gute Biene zum bösen Spiel", description = "Oh, gepriesen sei die Lebensbinderin! Jemand mit einem Paar freier Hände!\n\nDiese Gärten sind üblicherweise ein wundervoller Spielplatz für unsere Welpen, aber seitdem hier alles aufblüht, vermehren sich die Bienen unkontrolliert. Die Blumen vermehren sich geradezu prächtig, und damit auch die Bienen. Die Welpen sind verängstigt, die Drachen sind genervt und gestern erst wurde einer von ihnen gestochen...\n\n<Vaeros atmet tief durch, um sich zu beruhigen, und sieht Euch dann flehend an.>\n\nKönntet Ihr bitte die Bienen einfangen und sie an den See umsiedeln? Nehmt diesen Rauchdiffusor, damit könnt Ihr sie beruhigen.", sourceObjective = "Beruhigt mit dem Rauchdiffusor 8 lästige Bienen, sammelt sie ein und lasst sie in der Nähe des Sees frei.", completion = "Bitte sagt mir, dass die Umsiedlung gut geklappt hat.\n\n<Vaeros seufzt zutiefst erleichtert auf.>\n\nHoffentlich werden die Bienen fleißig die Pflanzen dort bestäuben, weit entfernt von unseren Welpen. Habt Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[66735] = { id = 66735, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnippschnapp", description = "Dass die Bienen die Welpen verschrecken, ist nicht das einzige Problem. Während die Bestäubung normalerweise eine gute Sache ist, hat der jüngste Schwarm die Flora außer Kontrolle geraten lassen.\n\nKönntet Ihr bitte meine Gartenschere nehmen und die Sträucher zurückschneiden? Einige haben bereits begonnen, gefährliche Wucherungen auszubilden, aber ich hoffe, wir können weitere davon abhalten, dies zu tun. Vorsicht ist ja bekanntlich besser als Nachsicht.\n\nUnd ich könnte gerade... wirklich eine ordentliche Portion Vorsicht brauchen, {name}.", sourceObjective = "Schneidet 5 überwuchernde Sträucher zurück.", completion = "Habt Dank, {name}. Mit etwas Glück werden den Welpen jetzt weniger Bienen begegnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66737] = { id = 66737, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein guter Anfang", description = "Vaeros ist gewissenhaft, doch Welpen haben ein angeborenes Talent für Ärger. Meine stellen natürlich eine Ausnahme dar... doch nicht alle Drachen ziehen ihre Gelege auf und können die Bedeutung dieser Station nachvollziehen.\n\nEs widerstrebt mir zutiefst, Außenaktivitäten Vorzug gegenüber dem Studium zu geben, doch ich werde Euch helfen, den Garten effektiver zu schützen. Nehmt diese Samenkörner und pflanzt sie in der Nähe ein. Sobald sie erblüht sind, vertreibt ihr Duft die meisten Insekten.\n\nDie Gärtner können Euch helfen... und vielleicht auch meine bronzenen Brüder und Schwestern, wenn Ihr Euch benehmt.", sourceObjective = "Pflanzt Samen in 6 Felder mit fruchtbarer Erde und lasst sie aufwachsen.", completion = "Es überrascht mich, dass Ihr Euch nur einen Tadel von Veladormi eingeholt habt. Sie muss heute gnädig gestimmt sein.\n\nIch nehme an, dass das Insektenproblem jetzt gelöst ist. Gern geschehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66777] = { id = 66777, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uktuluter Küstenachter", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[66778] = { id = 66778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uktuluter Küstenachter - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[66779] = { id = 66779, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ersichtlicher Erbe", description = "Als Erbe Neltharions und Anführer des einzig überlebenden Schwarms der schwarzen Drachen hatte ich nicht erwartet, mein Geburtsrecht verteidigen zu müssen. Und schon gar nicht gegen einen selbstherrlichen Welpen, der jünger ist als Ihr, <Sterblicher/Sterbliche>.\n\nDessen ungeachtet braucht Ihr mir nicht aufs Wort zu glauben und könnt gerne mit den Mitgliedern meines Schwarms sprechen, wenn Euch diese offensichtlichen Fakten nicht genügen.", sourceObjective = "Sprecht mit den Anhängern von Sabellian.", progress = "Mein Schwarm erwartet mich.", completion = "Ich denke, Ihr versteht jetzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[66780] = { id = 66780, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thronanwärter", description = "Ich habe mich immer wieder der Aufgabe gewidmet, Azeroth vor der Zerstörung zu bewahren, und dieser Narr glaubt, er könne einfach herabschießen und den Titel des Aspekts für sich beanspruchen? Ha.\n\nSprecht mit meinem Schwarm, {name}. Hört Euch an, was er über mich zu sagen hat und was ich für diese Welt getan habe.", sourceObjective = "Sprecht mit Furorions Anhängern.", progress = "Ihre Treue ist über jeden Zweifel erhaben.", completion = "Ihr seid doch auf meiner Seite, nicht wahr, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[66781] = { id = 66781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Frage des Geschmacks", description = "So viel Respektlosigkeit hier!\n\nEin paar stinkende Gorlocs klauen Teile unserer Ausrüstung und schon müssen wir alles stehen und liegen lassen... Ha! Ich hab schon Steine geleckt, da habt Ihr noch in die Windeln gemacht! Dazu brauch ich keine gnomischen Spielereien.\n\nBringt mir einen Stein und ich werd's Euch beweisen!", sourceObjective = "Findet einen Stein, an dem Mordigan Eisenkiefer lecken kann, in Walfängerwinkel.", progress = "Schon einen guten Stein gefunden?", completion = "Perfekt! Macht Euch bereit, die beeindruckendste Darstellung der Geologie zu beobachten, die Ihr je gesehen habt!", sourceObjectiveStatus = "unverified-source-field" }
quests[66783] = { id = 66783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erneuerung der Gelübde", description = "Vor Jahrhunderten habe ich einen Schwur der Freundschaft und Zusammenarbeit mit den ersten Zentauren geschlossen. Obwohl sich seitdem viel geändert hat, finde ich, dass es an der Zeit für uns ist, diesen Schwur zu erneuern.\n\nEs wurde eine Rezitation verfasst, um zukünftigen Zentaurengenerationen zu helfen, sich an ihren Bund mit dem grünen Drachenschwarm zu erinnern. Jeder Vers muss mit einer Opfergabe der Khane beantwortet werden. Ich hoffe, die Zentauren erinnern sich noch an ihre ursprünglichen Bedeutungen.\n\nDie Wahl der Gabe ist entscheidend. Wählt die richtige Opfergabe und unser Bündnis ist geschlossen.", sourceObjective = "Helft Sansok Khan, Tigari Khan, Khanam Matra Sarest und Merithra, Gaben auszutauschen.", progress = "Die Worte lauten:\n\nVon den Jägern, welche das Können über alles stellen, ein Ritus des Übergangs: ein Erstes.\n\nVon den Mystikern, welche mit dem Wind Zwiesprache halten, ihre leichteste Berührung: ein Auftrieb.\n\nVon den Abkömmlingen der Matriarchin, ein Tropfen ungebrochener Nachfahrenschaft: eine Linie.", completion = "Jetzt, da unser Bündnis erneuert wurde, kann sich uns niemand mehr in den Weg stellen. Mit Wind und Flügel, so sei es.", sourceObjectiveStatus = "unverified-source-field" }
quests[66784] = { id = 66784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Sturm aushungern", description = "Ihr schlagt Euch nicht schlecht, wenn man bedenkt, dass Euch nur zwei Beine zur Verfügung stehen!\n\nEs spielt keine Rolle, wie gut wir uns schlagen, solange die Primalisten weiterhin Verstärkung erhalten. Wir müssen dieses Portal schließen, den Sturmkorridor!\n\nSchlagt Euch zu der nahe gelegenen Höhle durch und tötet die Sturmbeschwörer der Primalisten, die das Portal geöffnet halten. Ich werde Euch beistehen, wenn ich kann.", sourceObjective = "Tötet alle Sturmbeschwörer der Primalisten, um das Sturmkorridorportal zu schließen.", progress = "All dies hat keinen Sinn, wenn das Portal geöffnet bleibt!", completion = "Jetzt, da wir die Verstärkung unseres Feindes abgeschnitten haben, geht der Kampf in die entscheidende letzte Phase. Gute Arbeit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[66785] = { id = 66785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die letzte Eierhüterin", description = "Ich kann Eure Sorge nachvollziehen, {class}, aber alles wird bald richtiggestellt werden, da es aussieht, als ob wir bald Besuch bekommen.\n\nBleibt, wenn Ihr möchtet, und beobachtet, was passiert. Es sollte recht reinigend wirken.\n\nDoch sprecht mit unserer Eierhüterin, wenn Ihr einen Moment Zeit habt. Sie könnte Eure Unterstützung brauchen.", sourceObjective = "Sprecht mit Mutter Elion.", completion = "Könnt Ihr das glauben?", sourceObjectiveStatus = "unverified-source-field" }
quests[66786] = { id = 66786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwingenrastkreisel", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[66787] = { id = 66787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwingenrastkreisel - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[66788] = { id = 66788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "BegEIstert von der Zukunft", description = "Ich kann es kaum glauben! Eier des schwarzen Drachenschwarms! Nach all der Zeit!\n\nAber seht nur, in welchem Zustand sich dieser Ort befindet! Das darf auf keinen Fall so bleiben! Für diese Eier ist nur das Beste gut genug.\n\nAllerdings haben diese beiden Wichtigtuer, die wie Kleinkinder um die Gunst der Lebensbinderin zanken, sicherlich keinen Gedanken an uns verschwendet! Ihr hingegen werdet eine alte Eierhüterin doch nicht im Stich lassen, nicht wahr?", sourceObjective = "Helft Mutter Elion, das Gebiet wiederherzustellen.", progress = "Wir sind noch nicht fertig, mein Kind.", completion = "Habt Dank, {name}. Ich habe das Gefühl, wir haben vielleicht wieder eine Zukunft.", sourceObjectiveStatus = "unverified-source-field" }
quests[66805] = { id = 66805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlüssel der Loyalität", sourceObjective = "Sammelt 1 große Obsidianschlüssel.", sourceObjectiveStatus = "unverified-source-field" }
quests[66814] = { id = 66814, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tyrs Urteil", description = "Willkommen im Verhüllten Ossuarium. Ursprünglich als Ruhe- und Gedenkstätte der Toten gebaut. Heute vermutlich der Ort, an dem sich der Stein befindet, den wir Tyrs Urteil nennen.\n\nUns liegen keinerlei Berichte vor, dass in der Umgebung Splitterflammen gesichtet wurden, doch die Expedition hat gelernt, dass sie sich gerne bis zum Angriff bedeckt halten.\n\nSeid also auf der Hut, {name}.", sourceObjective = "Erlangt Tyrs Urteil zurück.", progress = "Ich wollte mich eigentlich immer nur dem Studium widmen. Stattdessen wühle ich mich jetzt durch Schutt und werde von drakonischen Geistern gejagt.", completion = "Tyr hat das einst in Händen gehalten. Unglaublich.", sourceObjectiveStatus = "unverified-source-field" }
quests[66825] = { id = 66825, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine rubinrote Lebensberufung", sourceObjective = "Nehmt an der lebensberufenden Zeremonie beim Rubinlebensschrein teil.", completion = "Eine Berufung kann sich im Laufe des Lebens einer Drachenbrut ändern, aber wir alle halten unsere erste in Ehren. Danke, dass Ihr an unserer Zeremonie teilgenommen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[66827] = { id = 66827, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Blumen unserer Arbeit", description = "Den Legenden zufolge singt die Stimme nur für diejenigen, die ihre Hingabe für das Leben beweisen.\n\nIch habe mich jahrelang um diesen Garten gekümmert. Und ich glaube, dass meine Pflanzen und ich endlich bereit sind.\n\nIch bereite hier beim Teich schon mal alles vor. Ihr könnt mir währenddessen bei der Ernte helfen!\n\nSammelt Samenkapseln von den Büschen, Drachenblumen auf den sonnigen Feldern und Drachenfrüchte hoch oben in den Bäumen. Für Letztere könnt Ihr Euch gerne meine alte Harke leihen. Und passt auf! Die Blätter können recht angriffslustig sein!", sourceObjective = "Sammelt 5 gereifte Drachenfrüchte, 5 duftende Drachenblumen und 5 üppige Samenkapseln im Garten, um sie dem Drachengeist darzubieten.", progress = "<Akora spricht nervös mit sich selbst.>\n\nEinfach nur an die Mantras erinnern...\n\nWillst du süße Früchte besitzen,\nmusst du die Luft erhitzen.\n\nSich um den Boden früh zu sorgen,\nvertreibt alle Erntesorgen.\n\nSoll ein Baum Früchte gebären,\nmusst du seine Wurzeln ehren...", completion = "Nun... zumindest den Tieren scheint meine Arbeit zu gefallen.\n\n<Akora bemüht sich zu lächeln, kann aber ihre Enttäuschung nicht verbergen.>\n\nVielleicht war die Legende niemals wahr.", sourceObjectiveStatus = "unverified-source-field" }
quests[66828] = { id = 66828, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wirren in der Höhle", description = "Ich habe Akora noch nie so aufgebracht erlebt. Normalerweise ist ihr Gemüt so sonnig wie ihre Blumen, aber diese Legende bedeutet ihr sehr viel. Sie spricht die ganze Zeit darüber. Hm...\n\n<Keshki richtet sich die Brille.>\n\nIch weiß nicht viel über Pflanzen. Und ich glaube nicht, dass sich jemand außer mir über Frösche freuen würde...\n\nAber nördlich von hier gibt es einen ruhigen Ort, an den ich gerne zum Nachdenken gehe, die Flunkerhöhle. Vielleicht finden wir da etwas, das sie aufheitert... oder zumindest einen Plan, wie wir ihr helfen können.", sourceObjective = "Trefft Keshki bei der Flunkerhöhle.", completion = "Auch wenn ich Akora sehr gern aufmuntern möchte, {name}, es hat doch Priorität, dass ich mich um diese armen Frösche kümmere.\n\nFür den roten Drachenschwarm steht der Erhalt des Lebens an erster Stelle!", sourceObjectiveStatus = "unverified-source-field" }
quests[66830] = { id = 66830, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verflunkert nochmal!", description = "Oh, diese Flunker machen mich so wütend!\n\n<Keshki stampft so wütend mit dem Fuß auf, dass ihre Brille verrutscht.>\n\nGroße, gierige Fieslinge! Nur weil die Höhle nach ihnen benannt ist, heißt das nicht, dass sie überall rumspringen und alles fressen dürfen, was kleiner als sie ist!\n\nHier, nehmt meinen Krug mit Glühwürmchen... Das ist der beste Freund eines jeden Froschenthusiasten. Es beruhigt die Frösche so sehr, dass Ihr sie einsammeln und außer Gefahr bringen könnt.\n\nUnd wenn Euch ein paar Flunker in die Quere kommen, dann scheut Euch nicht davor, es ihnen heimzuzahlen!", sourceObjective = "Verwendet Keshkis Glühwürmchenkrug um 8 schikanierte Frösche in Sicherheit zu bringen.", progress = "Frösche sind sanftmütige Kreaturen! Es gehört sich nicht, sie derart herumzuschubsen!", completion = "Puh, alle Frösche, denen wir geholfen haben, sind jetzt in dem Behälter!", sourceObjectiveStatus = "unverified-source-field" }
quests[66831] = { id = 66831, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zuhause ist, wo die Frösche sind", description = "Wir haben alle Frösche beisammen, {name}! Ich schätze, wir bringen die Frösche so oder so zu Akora. Bei den Lebensbecken werden sie sicher sein, bis die Flunker das Interesse verlieren und weiterziehen.\n\nÄhm, nun ja, jetzt haben wir wohl nichts gefunden, um Akora aufzumuntern. Ich hoffe, dass sie das versteht...", sourceObjective = "Trefft Keshki bei den Lebensbecken, um die geretteten Frösche freizulassen.", completion = "Ich schätze, die Legende war und ist wahr.\n\n<Keshki grinst und blickt schüchtern zu Akora hinüber.>\n\nUnd vielleicht sind wir beide doch ganz gut darin, das Leben zu bewahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[66833] = { id = 66833, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marmoni in Bedrängnis" }
quests[66834] = { id = 66834, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rellen der Gelehrte", description = "Bringt Eure Opfergaben in die zentrale Höhle. Hier könnt Ihr die Legende von Rellen dem Gelehrten miterleben, der den Zentauren die Lebensgrundlage gab, wie wir sie heute kennen.", sourceObjective = "Bietet Eure Opfergaben in der Opferhöhle dar und erfahrt jede von Rellens Lehren.", progress = "Die Opferhöhle befindet sich in der Mitte von Teerakai.", completion = "Rellen hat die Grundlage für die Zentauren auf dieser Ebene gelegt. Ohne seine Lehren hätten wir niemals überlebt.", sourceObjectiveStatus = "unverified-source-field" }
quests[66835] = { id = 66835, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sonnentüpfelhainstrecke", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[66836] = { id = 66836, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sonnentüpfelhainstrecke - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[66837] = { id = 66837, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nichts zum Frühstück", description = "Mein Bruder Valdo hätte eigentlich Vorräte bestellen sollen. Aber es ist eine Woche vergangen und keine Lieferung ist angekommen.\n\nIch bin nicht überrascht. Der faule Sack hat stattdessen wahrscheinlich ein Nickerchen gemacht! Jetzt gehen uns die Lebensmittel aus und ich bin zu beschäftigt mit meinen... und Valdos Aufgaben, um auch noch auf die Jagd zu gehen!\n\nWürdet Ihr für uns auf die Jagd gehen? Das Fleisch der Vorquinschreiter und gestreiften Brüffelche südlich von hier würde die Küche gut aufstocken, bis ich wieder Vorräte bestellen kann.", sourceObjective = "Sammelt Fleisch von den Vorquinschreitern und gestreiften Brüffelchen südlich des Dreifällerundblicks.", progress = "Habt Ihr etwas Vorquinfleisch beschaffen können? Und einige Brüffelchspannrippen? Großartig! Ich hätte schon fast Stiefelfilet auf die Karte gesetzt...", completion = "Dank Euch... und trotz Valdo... kann ich diese hungrigen Reisenden bewirten!\n\nHmm... Sucht Ihr nach Arbeit? Ich habe da eine \"Ausschreibung\" am Laufen...\n\nIch kann Euch nicht viel zahlen, aber Ihr könnt Valdos Platz haben! Nein? Naja, einen Versuch war es wert.", sourceObjectiveStatus = "unverified-source-field" }
quests[66838] = { id = 66838, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es ist kalt hier oben", description = "Eine gute Wirtin muss die Wünsche der Gäste vorhersehen können. Leider war ich nicht darauf vorbereitet, wie kalt die Nächte hier draußen werden können. Hoppla?\n\nMeine Gäste werden Decken brauchen... gute, dicke Decken. Vielleicht Bärenpelze?\n\nIn den Wäldern östlich von hier leben einige große Bären. Wenn Ihr mir einige ihrer Pelze bringt, werde ich Euch gut bezahlen!\n\nBitte? Denkt doch nur an die Abenteurer und ihre kalten, kalten Füße...", sourceObjective = "Sammelt dicke Bärenpelze von Dichtmähnenbären.", progress = "Hä? Oh! Ihr seid schon zurück?\n\nVerzeiht, ich war in mein Kartenspiel vertieft...\n\nHabt Ihr die Pelze?", completion = "Oh! Die sind großartig! So luxuriös und weich...\n\nWenn nur Valdo hier wäre, um sie zu säubern!", sourceObjectiveStatus = "unverified-source-field" }
quests[66839] = { id = 66839, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brauzeit!", description = "Wir Kumpel hatten ein wenig Freizeit und Lust auf ein Bier, also sind wir zum Gasthaus gelaufen.\n\nAber, ach, kaum zu fassen! Die hatten nichts zum Trinken! Was ist das für ein Saftladen? Einer von den Läden der Steinangels, so einer!\n\nAlso nehmen wir's selber in die Hand! Im Wald östlich von hier gibt es ein paar Blumen und Kräuter, aus denen wir einen süßen Met brauen könnten. Wollt Ihr mir helfen und ein paar Blumen pflücken? Es wird sich lohnen!", sourceObjective = "Sammelt Blutbeeren, Bronzehornbeeren und Drachenblattblüten.", completion = "Oh, die sind wun-der-voll! Diese ist würzig! Und die erinnert mich an Erdwurzel. Oh, ich kann den Met schon schmecken.\n\nVielen Dank, Kumpel! Ihr habt mir und den Jungs den Tag gerettet!", sourceObjectiveStatus = "unverified-source-field" }
quests[66840] = { id = 66840, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wassersicherheit", description = "Meine wichtigste Pflicht ist sicherzugehen, dass für alle frisches Trinkwasser bereitsteht.\n\nMit den Gnollen im Osten und deren Verfall muss ich dafür sorgen, dass das Lager sicher ist.\n\nIch will niemanden verunsichern, indem ich Proben nehme, aber ich halte einen Test für notwendig.\n\nBringt mir Proben von den drei Wasserfällen in der Nähe. Ich werde Euch großzügig entlohnen.", sourceObjective = "Bringt drei Wasserproben zu Manny Lies.", completion = "Ein Tiefenwyrm?\n\nEtwas muss ihn aus seinem unterirdischen Nest vertrieben haben. Was auch immer dieses Eliteraubtier aufgeschreckt hat, muss wahrhaft schrecklich gewesen sein.\n\nHabt Dank, {name}, ich werde mich darum kümmern, dass der Kadaver entfernt wird, damit er nicht das Wasser verunreinigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[66841] = { id = 66841, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Fragment der Vergangenheit", description = "Ich hab Euch im Lager rumrennen und den Leuten helfen gesehen. Meint Ihr, Ihr könntet auch dem alten Gannar helfen?\n\nIch hab ein Gebiet untersucht und da ist mir was ins Auge gefallen. Ich glaube, es ist eine antike Tonscherbe oder ein Krug oder so, gleich südlich von hier am Rand des Wasserfalls.\n\nJetzt bin ich kein großer Schwimmer, aber ich würde Euch ein paar Münzen geben und Ihr bringt Euren Fund zu Thanessa Silberblüh.", sourceObjective = "Bergt das Artefakt und bringt es zu Thanessa Silberblüh.", progress = "Ihr müsst {name} sein.\n\nGannar sagte, Ihr erledigt irgendeinen Auftrag für ihn?", completion = "Das ist ein unfassbarer Fund! Ich habe noch nie antike Töpferkunst wie diese gesehen. Und diese Zeichnungen... Gebt mir einen Moment, um sie zu untersuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66843] = { id = 66843, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo ist Lukh?", description = "Ach! Habt Ihr meinen Assistenten, Lukh, gesehen?\n\nDer Junge wollte sich kurz umsehen, aber er ist seit einer Stunde verschwunden!\n\nIch habe ihm gesagt, es ist hier nicht sicher genug für einen Spaziergang, aber der Junge ist so dickköpfig wie ein Widder.\n\nIch kann es ihm nicht übel nehmen. Es ist schön hier draußen, und er liebt Blumen.\n\nKönntet Ihr mir helfen, ihn zu finden? Mein Wagen und ich werden am Dreifällerundblick gebraucht!", sourceObjective = "Findet Lukh.", completion = "Vielen Dank, dass Ihr ihn gefunden habt! Ich wette, er streunt nicht noch einmal alleine herum.\n\nHier ist eine kleine Aufmerksamkeit für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[66844] = { id = 66844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der große Shokhari", description = "Von allen Tieren, die ich hier geseh'n hab, war keins so stolz, wie die große Himmelsfüchsin Shokhari.\n\nZu schade, dass sie 'nen Gnollschamanen gefress'n hat, weil sie jetz' vom Verfall verrückt geword'n ist. Als ich geseh'n hab, wie sie eins ihrer Jungen gefress'n hat, da wusst ich, dass was nicht stimmt.\n\nIch hab ihr die Jungen weggenommen, wollte sie herbring'n. Aber Shokhari hat mich angegriff'n und mich gut erwischt. Hätt's fast nicht überlebt.\n\nShokhari muss von ihrem Leid befreit werd'n. Wenn der Verfall noch mehr von ihrem Verstand befällt, hat sie's bald auf uns abgeseh'n.", sourceObjective = "Tötet Himmelsfüchsin Shokhari.", completion = "Oh, es ist 'ne traurige Zeit für mich, aber es musste sein.\n\nHier, nehmt eins von Shokharis Jungen. Ich kann sie nich' alle behalten. Uns um sie zu kümmern, ist das Mindeste, was wir tun könn'.\n\nZieht's gut auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[66845] = { id = 66845, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine wahre Rarität", description = "Letzte Nacht, als ich unter meiner Decke lag und versuchte, in den Schlaf zu finden, füllte plötzlich eine unnatürliche Kälte das Gasthaus.\n\nDann erschien aus dem Nichts der Geist eines Drakoniden! Er hat mein Gepäck durchsucht und sich danach in Luft aufgelöst!\n\nAls ich heute Morgen erwachte, war das Erschreckendste daran aber, dass der Geist meine Lieblingskarte gestohlen hatte!\n\nWärt Ihr so lieb, den Geist für mich aufzuspüren und mir meine Karte zurückzubringen? Sie ist mein wertvollster Besitz.", sourceObjective = "Findet den Geist des Drakoniden und nehmt ihm die legendäre Karte ab.", completion = "Die Erscheinung hat sich erklärt und um Vergebung gebeten.\n\nDoch dann wollte sie eine Einzelpartie mit mir spielen.\n\nUnser Spiel unterscheidet sich scheinbar sehr von dem, was sie einst gespielt hat, weshalb sie es ausprobieren wollte.\n\nDanke, dass Ihr uns beiden geholfen habt. Vielleicht macht die Partie ja Spaß?", sourceObjectiveStatus = "unverified-source-field" }
quests[66846] = { id = 66846, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Karte des Herzens", description = "Der Tag, an dem die Dracheninseln in ihren Schlummer verfielen, war auch der Tag meines letzten Spiels. Das Schicksal war grausam: Ich verlor meine stärkste Karte, bevor ich antreten konnte.\n\nIhr müsst wissen, dass Guo-Hees Karte früher meine war. Ich weiß nicht, wie ihre Vorfahren in den Besitz dieser Karte gekommen sind.\n\nUnd leider kann ich sie jetzt nicht zurückfordern, nachdem sie seit Generationen in ihrem Familienbesitz war. Das war wirklich dumm von mir.\n\nVielleicht könnten wir beide zusammen eine Karte herstellen. Eine wirklich einzigartige Karte. Ja! Werdet Ihr mir helfen?\n\nGebt mir Bescheid, wenn Ihr bereit dafür seid.", sourceObjective = "Helft der Erscheinung, eine neue Karte herzustellen.", progress = "Die Karte, die wir herstellen, muss ebenfalls mächtig sein. Ich werde Eure Hilfe dabei brauchen!", completion = "Ja! Eine solche Karte habe ich noch nie zuvor gesehen! Diese Macht! So viele Möglichkeiten!\n\nFabelhaft!\n\nHabt Dank, {name}. Ich bin nun bereit...", sourceObjectiveStatus = "unverified-source-field" }
quests[66847] = { id = 66847, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewölbe der Inkarnationen: Zorn der Sturmfresserin", description = "Nein! Wir haben die Inkarnationen eingeschlossen, um diese Welt zu retten, und nun will Raszageth sie befreien!\n\nDas darf ihr nicht gelingen, {name}. Alles Leben auf Azeroth schwebt in großer Gefahr, wenn Ihr sie nicht aufhaltet!\n\nIch muss zu Nozdormu im Sitz der Aspekte zurückkehren und mich auf das vorbereiten, was da kommt.\n\nKhadgar und Kalecgos warten drinnen bereits mit einem Trupp Verbündeter. Schließt Euch ihnen an, um Raszageth ein Ende zu machen.\n\nViel Glück, Champion.", sourceObjective = "Betretet das Gewölbe der Inkarnationen und besiegt Raszageth.", progress = "Habt ihr Raszageth aufgehalten? Wir dürfen sie nicht einfach machen lassen, {name}.", completion = "Das sind schreckliche Neuigkeiten, {name}. Azeroth ist wieder in Gefahr, aber Khadgar hat recht.\n\nWir dürfen die Hoffnung nicht verlieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[66848] = { id = 66848, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeichen im Wind", description = "Ohn'ahra spricht nicht in einer Sprache, wie wir es tun. Der Wind trägt ihre Stimme. Wir Mystiker haben uns darin geübt, ihre Präsenz zu erspüren, ihrem Ruf zu folgen und ihre Nachrichten zu deuten.\n\nIch habe die Materialien, die Ihr gesammelt habt, genutzt, um Totems an diesen besonderen Ruf zu binden. Helft mir mit dem Ritual, ihre Stimme zu konzentrieren. Dann werde ich ihr Lied deuten.", sourceObjective = "Helft Ohn Seshteng bei ihrem Ritual.", progress = "Ohn'ahras Stimme umgibt uns... Ihr müsst ihr nur lauschen.", completion = "Der Sturm ist ein finsteres Omen. Ärger braut sich zusammen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66856] = { id = 66856, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sabrina Schwarz und die sieben Gnome", description = "Die Djaradin haben die Obsidianzitadelle geplündert und dabei einige wertvolle Artefakte gestohlen.\n\nFurorion hat uns aufgetragen, jedes aus der Zitadelle entwendete Artefakt zurückzubringen. Mein Team hat in der Umgebung mehrere ausfindig gemacht, wir könnten allerdings Eure Hilfe brauchen.", sourceObjective = "Holt die gestohlenen Artefakte zurück.", progress = "Habt Ihr alles auf der Liste finden können?", completion = "Ausgezeichnete Arbeit, {name}. Wir melden uns bei Euch, sobald wir mehr der gestohlenen Artefakte aufgespürt haben und wieder Eure Hilfe brauchen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[66858] = { id = 66858, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besucht den Handelsposten", description = "<Ein Flugblatt, getragen vom Wind, landet in Euren Händen.>\n\nSeid Ihr ein Sammler, Händler oder Abenteurer?\n\nWir sind durch ganz Azeroth gereist, um Waren der besten Qualität für jemanden wie Euch zu sammeln!\n\nBesucht uns in einem unserer Außenposten in Sturmwind oder Dornogal und stöbert in den neuesten Waren!\n\n- T&W-Handelsposten\n\n<Ihr müsst Euch anstrengen, um das Kleingedruckte entziffern zu können.>\n\nZeigt dieses Flugblatt für Bonushändlerdevisen vor!", sourceObjective = "Nehmt Eure Händlerdevisen aus der Truhe des Sammlers und besucht den Handelsposten.", progress = "Willkommen beim Handelsposten!\n\nWir haben Waren aus ganz Azeroth für Euch. Wollt Ihr einen Blick drauf werfen?", completion = "Jetzt, wo Ihr den Laden besucht und unsere Waren gesehen habt, kann ich Euch noch ein paar Handelsdevisen für das Flugblatt geben.\n\nWenn Ihr Euch noch mehr davon verdienen wollt, dann schaut doch im Reisetagebuch innerhalb des Abenteuerführers nach, was es für Aktivitäten gibt. Wenn Ihr genug davon abschließt, belohnen wir Euch mit Devisen und anderen wunderbaren Sachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66860] = { id = 66860, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reliktwiederbeschaffung: Vermächtnis von Tyr", description = "Kemora hat mich nach sämtlichen Hinweisen auf Hüter Tyr und Uldaman suchen lassen. Meine Papierschnitte haben eigene Papierschnitte von all den Büchern, dich ich für sie durchwühlt habe.\n\nFast alle Erwähnungen wurden herausgerissen oder vernichtet. Mit Ausnahme von der hier, die ich... ihr später zeigen will. Anscheinend wurde in Uldaman etwas Wertvolles versteckt. Es würde mich sehr freuen, wenn Ihr mir das bringen könntet.\n\nNatürlich nur, damit ich Kemora bei ihrer Forschung helfen kann.", sourceObjective = "Erbeutet das Stundenglas der Wandernden Sande von Chronolord Deios in Uldaman.", progress = "Habt Ihr es?", completion = "Fabelhaft!\n\nIch habe keine Ahnung, was das ist, aber es ist sicher sehr mächtig. Ich werde es an einem sicheren Ort aufbewahren... wo Kemora es später finden kann.\n\nIhr müsst es ihr nicht sagen, sie ist momentan sehr beschäftigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[66861] = { id = 66861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reliktwiederbeschaffung: Neltharus", description = "Ihr da! Die Djaradin waren viel, viel zu lange eine Bedrohung für das gesamte Drachenvolk und dank der Geheimnisse, die sie aus Neltharus gestohlen haben, sind sie jetzt nur umso mächtiger.\n\nGeht, findet, was Ihr könnt, und bringt es mir. Im Moment würde ich alles nehmen, was m... uns einen Vorteil ihnen gegenüber verschafft.\n\nOh und nehmt ein paar Freunde mit. Ihr haltet Euch sicher für stark, aber die Djaradin sind stärker. Glaubt mir.", sourceObjective = "Erbeutet das verzauberte Hirschhautsäckchen von Kriegsfürstin Sargha in Neltharus.", completion = "Eine Tasche? Ihr habt mir eine Tasche gebracht? \n\nNein, Ihr könnt sie nicht haben. Wer weiß schon, was darin ist? Ich muss nachsehen, ob sie etwas von Nutzen enthält... für unsere Forschung natürlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[66862] = { id = 66862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reliktwiederbeschaffung: Rubinlebensbecken", description = "Die Primalisten halten an ihrem Ansturm auf die Drachen in der Heiligkeit der Lebensbecken also fest? Widerwärtig. Diese Becken beinhalten die Zukunft der Drachen.\n\nIch bin sicher, Alexstrasza hätte nichts gegen etwas Hilfe einzuwenden, um die Primalisten zu vertreiben. Zeigt keine Gnade.\n\nOh ja... und bringt eine Trophäe zum Zeichen Eures Triumphs mit. Ich verabscheue jeden, der den Jungen nachstellt.", sourceObjective = "Erhaltet die Fangzähne von Kyrakka von Kyrakka im Rubinlebensbecken.", progress = "Habt Ihr Euch schon um die Primalisten gekümmert?", completion = "<Theldren nickt kalt angesichts Eurer Opfergabe.>\n\nAusgezeichnete Arbeit, {name}.\n\nAlle, die hier eintreten, sollen diese Zähne in unserem Regal sehen und den Zorn fürchten, der jenen entgegenschlägt, die sich gegen die Drachenschwärme stellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66863] = { id = 66863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reliktwiederbeschaffung: Der Angriff der Nokhud", description = "Die brutalen Nokhud auf den Ebenen von Ohn'ahra kämpfen unermüdlich gegen ihre Rivalen. Ihr Anführer Balakar ist ein furchterregender und gnadenloser Kontrahent, der sich nur selten geschlagen gibt.\n\nDie Geschichtenerzähler in Valdrakken erzählen von donnernden Hufen und Knochen knackenden Keulen, doch das lässt sich nicht damit vergleichen, einen Zentaurenkampf selbst zu erleben. Vielleicht solltet Ihr Euch das ein bisschen genauer ansehen? Dann könntet Ihr sogar eine Trophäe ergattern!\n\nMögen die Adler hoch über Euch wachen, {name}. Ich warte hier auf Eure Rückkehr.", sourceObjective = "Besorgt den blutbefleckten Großgürtel aus Moschushirschfell von Balakar Khan beim Angriff der Nokhud.", progress = "Schon so schnell zurück?", completion = "<Theldren begutachtet den Gegenstand genau.>\n\nAch du meine Güte, ist das frisches Blut? Ich werde das entfernen.\n\nWenn ich es mir allerdings recht überlege, gibt es dem Ganzen das gewisse Etwas. Es wirkt so authentisch. Findet Ihr nicht?", sourceObjectiveStatus = "unverified-source-field" }
quests[66864] = { id = 66864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reliktwiederbeschaffung: Brackenfellhöhle", description = "Ah! Ihr könnt mir helfen. Die Gnolle der Brackenfellhöhle sollen angeblich Verfall einsetzen, ein mächtiges Werkzeug in den richtigen Händen. Gnolle haben nicht die richtigen Hände.\n\nWir sollten gebührende Nachforschungen in dieser dringenden Angelegenheit anstellen. Geht in die Höhle und bringt etwas von ihrer Magie mit, damit ich... damit wir sehen, welche Mächte sie sich zunutze gemacht haben.\n\nAber seid vorsichtig und geht nicht allein. Die Brackenfellgnolle können Eure Knochen zu Staub zerfallen lassen.\n\nDas wäre jammerschade.", sourceObjective = "Besorgt den Fetisch der Faultriarchin von Faultriarchin Zornauge in der Brackenfellhöhle.", completion = "Was habt Ihr da gefunden? Gebt schon her!\n\nJa... das wird mir gute Dienste leisten...\n\nFür unsere Forschungen natürlich. Jetzt geht... und danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[66865] = { id = 66865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reliktwiederbeschaffung: Das Azurblaue Gewölbe", description = "Das Azurblaue Gewölbe soll einige der ältesten und mächtigsten Artefakte und Relikte beherbergen, die es gibt. Alles, was so viel Macht besitzt, muss gest... bewahrt werden.\n\nGeht, dringt in das Azurblaue Gewölbe vor und seht, was Ihr bergen könnt. Und nehmt ein paar Freunde mit. Dort wimmelt es vermutlich von allerlei gefährlichem magischen Unsinn.", sourceObjective = "Beschafft den Kristallfokus von Umbrelskul im Azurblauen Gewölbe.", progress = "Hier werdet Ihr nichts von Interesse finden, außer natürlich, Ihr wollt mit mir sprechen.", completion = "Was habt Ihr gefunden? Gebt es mir!\n\nOh, oh ja... das ist äußerst faszinierend. Ich bin sicher, ich... wir werden viel daraus lernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66866] = { id = 66866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reliktwiederbeschaffung: Hallen der Infusion", description = "Anscheinend hatte Hüter Tyr eine riesige Anlage unter Tyrhold. Kemora ist ganz aus dem Häuschen ob der \"Möglichkeiten\", was alles darin liegen könnte.\n\nSoweit ich weiß, hatte der Hüter alle möglichen Geheimnisse und Erfindungen. Nützliche. Wenn Ihr zufällig dort hineinstolpern und Euch umsehen würdet, könntet Ihr mir gewiss etwas... Faszinierendes bringen.\n\nOh ja, ein paar Primalisten könnten Euch zuvorgekommen sein. Erledigt sie, bevor sie all die guten Relikte der Titanen zerstören.", sourceObjective = "Beschafft den Kern der wässrigen Verderbnis vom urtümlichen Tsunami in den Hallen der Infusion.", progress = "Hmm? Was ist denn nun?", completion = "Wie nett von Euch, in eine geheime Einrichtung zu gehen, die von einem der brillantesten Hüter aller Zeiten geführt wurde, nur um mir... das zu bringen.\n\n<Theldren sieht abschätzig auf das Objekt herab, dann beginnt er, es intensiv zu mustern.>\n\nSchon gut. Ich meine... Ich werde es schon schaffen. Immerhin habt Ihr all das auf Euch genommen, um es mir zu beschaffen.\n\n<Ihr seht, wie er das Objekt neben sich platziert. Seine Augen springen hin und wieder dorthin, während ein geheimnisvolles Lächeln seine Mundwinkel umspielt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[66867] = { id = 66867, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reliktwiederbeschaffung: Akademie von Algeth'ar", description = "Die heiligen Hallen der Akademie von Algeth'ar sind legendär in der Drachenwelt. Ich hörte, dass die Zulassung sogar nicht mehr nur auf Drachen beschränkt ist.\n\nIhre Bibliothek ist spektakulär, dort finden sich Bücher, die selbst die Archive nicht haben.\n\nSagt... Wo sie doch neue Schüler aufnehmen, warum schreibt Ihr Euch nicht ein? Und wenn Ihr schon dort seid, besorgt Euch doch einen Bibliotheksausweis. Vielleicht könnt Ihr ja ein interessantes Buch für mich ausleihen. \n\nOh... Ich bin sicher, Kemora wäre ebenfalls interessiert.", sourceObjective = "Besorgt das Geschäftsbuch der Direktorin vom Echo von Doragosa in der Akademie von Algeth'ar.", progress = "Ja, ja. Wie verlaufen Eure Studien?", completion = "Das... ist alles, was Ihr zurückbringt? Ein Buchumschlag und sonst nichts?\n\nVielleicht sind die Seiten ja durch Magie verborgen. Hmmm...", sourceObjectiveStatus = "unverified-source-field" }
quests[66868] = { id = 66868, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Vergangenheit bewahren: Vermächtnis von Tyr", description = "Ich habe die Archive nach Informationen über Hüter Tyr durchsucht und war überrascht, dass sämtliche Hinweise auf Uldaman entfernt wurden. Nur auf einer halben Seite stand noch etwas über ein dort verborgenes Geheimnis.\n\nFaszinierend, oder? Ich wette, er hat dort auch noch andere Geheimnisse versteckt. Vielleicht könntet Ihr ja mal mit ein paar Freunden zusammen nachsehen. Ich wäre äußerst dankbar für alles, was Ihr mir bringen könnt.", sourceObjective = "Erbeutet die zeitverlorene Kuriosität von Chronolord Deios in Uldaman.", progress = "Habt Ihr etwas Interessantes gefunden?", completion = "Wunderbar! Das stammt zwar nicht wirklich von Tyr, aber es wird ausgezeichnet in die Archive passen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66870] = { id = 66870, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Vergangenheit bewahren: Rubinlebensbecken", sourceObjective = "Erhaltet das urenergieerfüllte Drachenei von Kyrakka im Rubinlebensbecken.", progress = "Ja? Habt Ihr mir etwas mitgebracht?", completion = "Ich kann Euch gar nicht genug danken. Ich werde sofort mit den Forschungen beginnen. Wenn es eine Möglichkeit gibt, alles rückgängig zu machen, was die Primalisten getan haben, muss ich danach suchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66871] = { id = 66871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Vergangenheit bewahren: Der Angriff der Nokhud", description = "Im Westen toben Kriege. Blutgetränkte Landstriche, Schlachten und Leben, die die Schmerzen endloser Kämpfe ertragen müssen. Dies ist unser Vermächtnis, {name}.\n\nAber jenseits davon liegt unsere Zukunft. Für diese Zukunft müssen wir bewahren, was von unserer Geschichte und Kultur übrig geblieben ist, bevor die Erinnerung daran verblasst.\n\nBegebt Euch nach Westen. Sucht die Armeen der Khanam Matra auf und arbeitet mit unseren Verbündeten zusammen, um das Leid der Maruuk zu beenden.\n\nGute Reise, {name}. Möge Ohn'ahra Euch führen.", sourceObjective = "Beschafft die Feder der Himmelsmutter von Balakar Khan beim Angriff der Nokhud.", progress = "Wir müssen tun, was in unserer Macht steht, bevor es zu spät ist.", completion = "Wo... habt Ihr die her, {name}?\n\n\n\nWir werden dafür sorgen, dass sie die ihr gebührende Aufmerksamkeit erhält.", sourceObjectiveStatus = "unverified-source-field" }
quests[66873] = { id = 66873, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Vergangenheit bewahren: Das Azurblaue Gewölbe", description = "Das Azurblaue Gewölbe war der Hort für eine erstaunliche Menge antiker Relikte und Forschungen. Was für Wunder der blaue Drachenschwarm entdeckt haben muss!\n\nBitte, wagt Euch in das Azurblaue Gewölbe und seht, was Ihr dort finden könnt. Es gibt dort sicher vieles, von dem wir lernen können! Aber seid vorsichtig: Dies war der Lagerort für Dinge, die zu gefährlich waren, um in der Welt zurückgelassen zu werden.", sourceObjective = "Beschafft Sindragosas Aufzeichnungen von Umbrelskul im Azurblauen Gewölbe.", progress = "Welche uralten Geheimnisse werden wir heute aufdecken?", completion = "Die... arme Sindragosa. Den Schmerz eines Kindes miterleben zu müssen... Ich kann mir kaum vorstellen, was sie durchgemacht haben muss.\n\nEs bricht einem das Herz, aber man kann daraus etwas lernen. Bei der Erforschung uralter Magie muss man sehr vorsichtig sein. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[66874] = { id = 66874, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Vergangenheit bewahren: Hallen der Infusion", description = "Wusstet Ihr, dass es tief unter Tyrhold eine riesige Anlage gibt... die Hallen der Infusion? So geheimnisvoll! So fesselnd! So voller Möglichkeiten!\n\nHüter Tyr hat dort viele seiner Geheimnisse aufbewahrt. Ich frage mich, welche das sein mögen? Er war wirklich der genialste aller Hüter.\n\n<Kemora blickt verträumt.>\n\nAber die Primalisten richten gerade ein riesiges Chaos an. Sie werden wohl alle Wunder Hüter Tyrs zerstören, wenn sie nicht aufgehalten werden. Bitte, beseitigt sie, bevor sie zu viel Schaden anrichten.", sourceObjective = "Beschafft den holografischen Verteiler vom urtümlichen Tsunami in den Hallen der Infusion.", progress = "Habt Ihr mir ein Geheimnis mitgebracht? Oh! Ich bin ja so aufgeregt.", completion = "Oh. Das war also das Geheimnis, das Hüter Tyr verborgen hielt.\n\nNun, er hatte sicherlich gute Gründe für sein Handeln. Er hat immer vorausgedacht. Und wenigstens haben die Primalisten nicht alles zerstört.\n\nAber vielleicht würde mir dieses Objekt mit dem richtigen Schlüssel ein... netteres Geheimnis offenbaren.\n\n<Sie sieht Euch mit hoffnungsvollen, verträumten Augen an.>", sourceObjectiveStatus = "unverified-source-field" }
quests[66875] = { id = 66875, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Vergangenheit bewahren: Akademie von Algeth'ar", description = "Wie wundervoll! Die Akademie von Algeth'ar ist wieder geöffnet. Direktorin Doragosa ist sicher froh, wieder in ihren Hallen der Lehre zu sein.\n\nEs ist schon ein Weilchen her, dass ich die Gelegenheit hatte, mit meiner lieben alten Freundin zu sprechen. Vielleicht könntet Ihr hingehen und sehen, ob sie Euch zum Tee empfängt. Dann hättet Ihr auch die Möglichkeit, Euch an der Akademie einzuschreiben, denn ich hörte, dass sie jetzt für alle Studenten offen sei.\n\nIch dachte, das könnte Euch interessieren, so oft, wie Ihr mich und diese Archive besucht.", sourceObjective = "Beschafft den Traumirrwisch der verworrenen Erinnerungen von der Direktorin in der Akademie von Algeth'ar.", progress = "Geht und seht Euch die Akademie und all ihre Wunder an.", completion = "Oh, Doragosa! Ich erinnere mich... wir werden das mal beim Tee besprechen müssen.\n\nIch danke Euch, {name}. Ich nehme an, die Einschreibung verlief reibungslos?", sourceObjectiveStatus = "unverified-source-field" }
quests[66877] = { id = 66877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moor-Durchflug", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[66878] = { id = 66878, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moor-Durchflug - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[66879] = { id = 66879, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hornschreiterchaos", description = "Hornschreiter! Sie haben Schnäbel, mit denen sie Knochen knacken, schnelle Beine, mit denen sie Gefahren entkommen, und Mägen, die so ziemlich alles auf den Inseln vertragen.\n\nDas ist die mit Abstand einfachste Berufung! Nur ich zusammen mit meinen liebsten großen Vögeln. Und sollte doch mal was sein, weiß ich, wie man alle Kreaturen der Inseln wieder in den Griff bekommt.\n\nWürde es Euch etwas ausmachen, mich zu den Plateaus der Hornschreiter im Norden zu begleiten? Ich könnte ein zusätzliches Paar Hände brauchen, während ich mich einrichte.", sourceObjective = "Trefft Dazakros bei den Überlaufenden Stromschnellen.", completion = "Ich habe so viele Bücher über Hornschreiter gelesen und habe mit dem größten Donnerechsenjungen gerungen, das Ihr je gesehen habt... doch über Wasserelementare weiß ich wirklich gar nichts!", sourceObjectiveStatus = "unverified-source-field" }
quests[66880] = { id = 66880, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schluchtflusslauf", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[66881] = { id = 66881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schluchtflusslauf - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[66882] = { id = 66882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verlorenes Gefechtspaket", description = "<Krallenpirscherin Kavia könnte das haben wollen.>", sourceObjective = "Bringt den Gegenstand zu Krallenpirscherin Kavia.\n\nBereitgestellter Gegenstand:", completion = "Es ist noch intakt. Hoffentlich bringt es seinem nächsten Besitzer mehr Glück.", sourceObjectiveStatus = "unverified-source-field" }
quests[66883] = { id = 66883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uralter Hornring", description = "<Exadria könnte das haben wollen.>", sourceObjective = "Bringt den Gegenstand zu Exadria.\n\nBereitgestellter Gegenstand:", completion = "Ein uralter Hornring? Er sollte getragen werden, um die zu ehren, die vor uns in der Schlacht gefallen sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[66884] = { id = 66884, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuerfeste Ausrüstung", description = "Die Rüstung der Djaradin kann sogar tosenden Flammen standhalten. So etwas wäre für uns sehr nützlich, wenn wir sie bekämpfen wollen!\n\nSeht, was Ihr von den Djaradin beschaffen könnt. Dann können wir die Teile untersuchen und dieselben Verzauberungen auf unsere eigenen Rüstungen anwenden.", sourceObjective = "Sammelt 10 feuerfeste Ausrüstungsgegenstände von den Djaradin der Dracheninseln für Temnaayu von den Tuskarr von Iskaara.", progress = "Konntet Ihr Ausrüstungsteile beschaffen?", completion = "Das sind perfekte Exemplare für unsere Untersuchungen! Jetzt sollten wir unsere Rüstungen verbessern können.\n\nVielen Dank für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[66885] = { id = 66885, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smaragdgärtenaufstieg", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[66886] = { id = 66886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smaragdgärtenaufstieg - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[66890] = { id = 66890, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestohlene Werkzeuge", description = "Wir werden von Gnollen geplagt, die unsere Versorgungskarawanen angreifen. Sie scheinen von den Ingenieurswerkzeugen, die damit transportiert werden, regelrecht besessen zu sein. Wir können nicht riskieren, dass gewalttätige Plünderer unsere spezialisierten Werkzeuge verstehen lernen! Außerdem haben die Diebstähle unserem Produktionsfortschritt mehr geschadet, als ich zugeben möchte.\n\nWenn Ihr einige der gestohlenen Ingenieurskunstwerkzeuge zurückerlangen könntet, wären wir wieder im Zeitplan.", sourceObjective = "Sammelt 20 gestohlene Werkzeuge von den Gnollen der Dracheninseln für Dothenos vom Valdrakkenabkommen.", progress = "Habt Ihr die gestohlenen Werkzeuge beschafft?", completion = "Diese Bauteile werden uns helfen, den Zeitplan unserer Ingenieursprojekte doch noch einzuhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[66891] = { id = 66891, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explosive Asche", description = "Die geschmolzenen Phönixe der Dracheninseln hinterlassen eine ungewöhnliche Aschesubstanz, wenn sie sterben. Man könnte sie nutzen, um einige Materialverstärkungen für komplexe, lebensverändernde Maschinen herzustellen. Obwohl ich sie wahrscheinlich eher für Sprengstoff nutzen würde.", sourceObjective = "Sammelt 20 Teile explosiver Asche von den Phönixen auf den Dracheninseln für Gnoklin Quirkspule von der Drachenschuppenexpedition.", progress = "Habt Ihr schon genug Asche gefunden?", completion = "Diese Asche könnte einen essenziellen Bestandteil vieler Maschinen darstellen, die das Leben für Leute auf ganz Azeroth verbessern würden. Aber wem mache ich etwas vor? Wir werden Sprengstoff daraus herstellen! BUMM!", sourceObjectiveStatus = "unverified-source-field" }
quests[66892] = { id = 66892, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wasserwahnsinn", description = "Elementare töten die Hornschreiter! Ich weiß, wie man große Kreaturen in den Griff bekommt, doch ich hätte nie gedacht, es mit einem Elementar aufnehmen zu müssen! Die sind nicht mit Donnerechsenjungen zu vergleichen...\n\n<Dazakros seufzt betrübt auf.>\n\nTut mir bitte einen Gefallen und erledigt ein paar dieser Elementare. Hornschreiter haben mehr Verstand, als wir ihnen zutrauen. Sie werden sie sich schon wehren, wenn sie können!", sourceObjective = "Tötet 12 Wasserelementare bei den Überlaufenden Stromschnellen.", completion = "Und ich dachte schon, ich hätte alles gesehen. Schaut Euch nur an, wie die Kleinen sich von der Quelle fallen lassen...\n\nAnscheinend ist das Leben als Pflegerin doch nicht so einfach wie gedacht. Vielen Dank für Eure Hilfe, {name}. Ich habe viel von Euch gelernt!", sourceObjectiveStatus = "unverified-source-field" }
quests[66893] = { id = 66893, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnabelhafte Rückgewinnung", description = "Über Wasserelementare weiß ich zwar nichts, aber mit Hornschreitern kenne ich mich aus!\n\nIch habe eine Salbe zusammengestellt, die die Schreiter gesund und kampfbereit hält. Ich hatte noch nie die Gelegenheit, sie einem echten Hornschreiter zu verabreichen, aber ich habe so viel geübt, wie ich nur konnte.\n\nEs wird Zeit, unseren ganzen Mut zusammenzunehmen und unsere Freunde damit einzuschmieren!", sourceObjective = "Heilt 8 verletzte Hornschreiter bei den Überlaufenden Stromschnellen.", completion = "Es ist wirklich erbaulich zu sehen, wie die Hornschreiter ihre Heimat zurückgewinnen. Und das haben sie Euch zu verdanken, {name}. Vielen Dank für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[66894] = { id = 66894, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So wie der alte Boss", description = "Die Weltenbrecherdrachkin sind ein vertrauensvoller Haufen. Über die Jahre hinweg sind wir vielen Anführern gefolgt, in der Hoffnung, dass sie uns zur Stunde des Zwielichts führen und die Rückkehr von Todesschwinge einläuten.\n\nAber Todesschwinge ist nicht zurückgekehrt und die Stunde des Zwielichts ist nie eingetreten.\n\nEs ist Zeit für einen neuen Anführer. Ihr könnt helfen, diesen Wechsel zu vollziehen.", sourceObjective = "Eliminiert Aizir den Entflammten.", progress = "Sind wir bereit für einen neuen Anführer?", completion = "Das habt Ihr gut gemacht. Jetzt gibt es reichlich Platz für den Aufstieg eines neuen Anführers, der die Weltenbrecher hoffentlich in eine bessere Zukunft führen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[66895] = { id = 66895, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So wie der alte Boss", description = "Die Weltenbrecherdrachkin sind ein vertrauensvoller Haufen. Über die Jahre hinweg sind wir vielen Anführern gefolgt, in der Hoffnung, dass sie uns zur Stunde des Zwielichts führen und die Rückkehr von Todesschwinge einläuten.\n\nAber Todesschwinge ist nicht zurückgekehrt und die Stunde des Zwielichts ist nie eingetreten.\n\nEs ist Zeit für einen neuen Anführer. Ihr könnt helfen, diesen Wechsel zu vollziehen.", sourceObjective = "Eliminiert Vyzos die Prophetin.", completion = "Das habt Ihr gut gemacht. Jetzt gibt es reichlich Platz für den Aufstieg eines neuen Anführers, der die Weltenbrecher hoffentlich in eine bessere Zukunft führen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[66896] = { id = 66896, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nett ins Netz", sourceObjective = "Sammelt 10 |4Warmwasserflussfisch:Warmwasserflussfische; und 6 |4saftiges Schnapperfilet:saftige Schnapperfilets;.", sourceObjectiveStatus = "unverified-source-field" }
quests[66897] = { id = 66897, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brennstoff für die Schmiede", description = "Um die besten Klingen herzustellen, braucht man eine Hitze, die nur ein Magmakern liefern kann. Wir versuchen, immer einige als Brennstoff für unsere Schmieden auf Lager zu haben. In letzter Zeit gehen uns aber die Kerne aus und wir könnten etwas Nachschub brauchen.\n\nMagmakerne lassen sich von den meisten Lavakreaturen auf den Dracheninseln erbeuten.", sourceObjective = "Sammelt 10 Magmakerne von den Lavakreaturen der Dracheninseln für Dhurrel von den Zentauren der Maruuk.", progress = "Habt Ihr die Magmakerne gesammelt?", completion = "Die Schmiede werden sich über diesen Nachschub für ihr Schmiedefeuer freuen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66899] = { id = 66899, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haarige Beinchen", description = "Wir haben eine Schneidereianfrage für \"Haarige Beinchen\" bekommen...\n\nSeht mich nicht so an, von mir stammen die Anfragen nicht, ich gebe sie nur weiter. Ich nehme an, die Beine von Taranteln würden die Anforderungen erfüllen.", sourceObjective = "Sammelt 20 haarige Beinchen von den Taranteln der Dracheninseln für Gnoklin Quirkspule von der Drachenschuppenexpedition.", progress = "Habt Ihr die haarigen Beinchen gesammelt?", completion = "Ich kann mir gar nicht vorstellen, was man damit anfangen soll, und ich will auch nicht darüber nachdenken. Aber trotzdem danke für Eure Mühe.", sourceObjectiveStatus = "unverified-source-field" }
quests[66900] = { id = 66900, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzauberte Relikte", description = "Ah, die Gezeiten tragen Euch gerade rechtzeitig hierher! Gnolle haben einige unserer Relikte gestohlen. Das waren besonders wertvolle Exemplare, weil sie verzaubert wurden. Wir können nicht zulassen, dass die Gnolle unsere Magie erlernen!\n\nJemand mit Euren Fähigkeiten sollte die gestohlenen Relikte ohne Weiteres identifizieren können. Bitte, könnt Ihr uns helfen?", sourceObjective = "Sammelt 10 verzauberte Relikte von den Gnollen der Dracheninseln für Temnaayu von den Tuskarr von Iskaara.", progress = "Habt Ihr die Relikte?", completion = "Ich fürchte mich vor dem, was die Gnolle über diese Relikte gelernt haben könnten, während sie in ihrem Besitz waren.\n\nDanke, dass Ihr sie zurückgeholt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[66901] = { id = 66901, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Welt zerbrechen" }
quests[66902] = { id = 66902, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinfort, Bienen!" }
quests[66903] = { id = 66903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufräumen des Gewölbes" }
quests[66921] = { id = 66921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maruukaispurt", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[66929] = { id = 66929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnappt sie Euch alle", sourceObjective = "Holt Yumadormus Kartenset zurück.", progress = "Ein paar der Karten konnte ich selbst rausholen. Habt Ihr den Rest schon bekommen?", completion = "Den Aspekten sei Dank! Die meisten sind noch intakt.\n\nIch konnte einen Weg finden, die Zeit für die Karten durch Bronzemagie umzukehren und sie wieder auf Vordermann zu bringen!", sourceObjectiveStatus = "unverified-source-field" }
quests[66931] = { id = 66931, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer macht hier Krach?", description = "Das war kein gewöhnliches Erdbeben.", sourceObjective = "Findet die Ursache für die Unruhe im Rubinlebensschrein.", progress = "Was könnte das sein?", completion = "Ich...\n\nSo sehr ich wünsche, meiner Königin in die Schlacht zu folgen, muss ich mich ihres Vertrauens würdig erweisen und den Lebensschrein beschützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66933] = { id = 66933, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spurt zum Spiegel des Himmels", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[66934] = { id = 66934, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Brecher brechen" }
quests[66935] = { id = 66935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallene Schreibfederkiele", description = "In diesem Gebiet leben einzigartige Kreaturen, die Kristallrücken. Eigentlich ganz niedliche kleine Wesen, aber sie sind durch ihre scharfen Kristallfederkiele sehr gut geschützt.\n\nAls ich einen unserer Forscher behandelte, der von einem solchen Federkiel verletzt worden war, fiel mir auf, dass eine gewisse, resonierende Macht in dem Federkiel erhalten geblieben war. Sie könnten eine exzellente Quelle für Verzauberungskristalle sein.", sourceObjective = "Sammelt 15 Kristallfederkiele von den Kristallrücken der Dracheninseln für Gnoklin Quirkspule von der Drachenschuppenexpedition.", progress = "Habt Ihr ein paar Kristallfederkiel gefunden?", completion = "Die sind eine perfekte Quelle für magisch resonierende Kristalle.", sourceObjectiveStatus = "unverified-source-field" }
quests[66937] = { id = 66937, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfallende Neuigkeiten", description = "Die Gnolle und die von ihnen eingesetzte Verfallmagie sind beunruhigend. Wir müssen so viel Wissen sammeln, wie wir können, falls die Bedrohung eskaliert.\n\nAls Alchemisten sind wir es gewohnt, solche widerwärtigen Substanzen gefahrlos zu sammeln - und sind außerdem den Geruch gewohnt. Werdet Ihr uns helfen?", sourceObjective = "Sammelt 10 verrottende Proben von den Fäulnisgnollen der Dracheninseln für Dothenos vom Valdrakkenabkommen.", progress = "Habt Ihr die verrottenden Proben gesammelt?", completion = "Wir werden diese Proben untersuchen. Es wird sich zeigen, ob wir eine alchemistische Lösung für dieses drohende Problem finden können.", sourceObjectiveStatus = "unverified-source-field" }
quests[66938] = { id = 66938, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mammutmark", description = "Neue und ungewöhnliche Gebräue zu kreieren, ist eines unserer vielen besonderen Talente. Wir lieben es zwar, mit unbekannten und faszinierenden Zutaten zu experimentieren, haben aber auch einige geläufige Zutaten auf Lager.\n\nEine dieser Zutaten ist das Mark aus Mammutstoßzähnen. Unsere Vorräte an Stoßzahnmark neigen sich dem Ende zu. Wir würden es wirklich zu schätzen wissen, wenn Ihr mehr für unsere Alchemisten sammeln könntet.", sourceObjective = "Sammelt 20 Einheiten Stoßzahnmark von den Mammuts der Dracheninseln für Dhurrel von den Zentauren der Maruuk.", progress = "Habt Ihr genug Stoßzahnmark gesammelt?", completion = "Die Alchemisten vom Klan der Maruuk werden höchst erfreut sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[66939] = { id = 66939, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Jagd auf den Meisterjäger", description = "Ich hörte von einer der Wachen im Lager im Nirgendwo, dass irgendein schändlicher Unhold die örtliche Tierwelt verstümmelt. Nennt sich selbst \"Meisterjäger\".\n\nJagen ist das eine, aber wenn jemand Lebewesen derart quält, kann ich nicht untätig bleiben. \n\nUnd außerdem, mein Wagen könnte einen Glücksbringer brauchen.\n\n<Nesingwary spuckt zur Seite.>\n\nBringt mir seine Pranken zurück.", sourceObjective = "Macht Jagd auf Meisterjäger Krakle nahe Imbus Schild.", progress = "Wie läuft die Jagd?", completion = "Ah, wie es scheint, wart Ihr erfolgreich.\n\nGut.\n\nHoffentlich können die Tierchen hier ab jetzt etwas beruhigter schlafen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66940] = { id = 66940, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elixierexperiment", description = "Unsere Alchemisten haben kürzlich eine Reihe neuer Zutaten für ihre Experimente ausprobiert. Ihr neuestes Interesse ist... interessant... um es vorsichtig auszudrücken.\n\nWie es scheint, weist Gorlocschleim einige Eigenschaften auf, die in bestimmten Elixieren sehr nützlich sind.", sourceObjective = "Sammelt 15 Einheiten Gorlocschleim von den Gorlocs der Dracheninseln für Dhurrel von den Zentauren der Maruuk.", progress = "Habt Ihr den Schleim von den Gorlocs gesammelt?", completion = "Wunderbar. Nun werden wir sehen, welche aufregenden Gebräue unsere Alchemisten daraus herstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66941] = { id = 66941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wunderbare Werkzeuge", description = "Die Djaradin verfügen über einige mächtig große Werkzeuge und Waffen. Wir haben für solches Werkzeug immer Verwendung, und sei es nur, um sie einzuschmelzen und daraus mehr Schmiedewaren für uns herzustellen.\n\nBringt mir einige Djaradinwerkzeuge, damit wir sie studieren und nutzen können.", sourceObjective = "Sammelt 10 große Werkzeuge von den Djaradin der Dracheninseln für Dhurrel von den Zentauren der Maruuk.", progress = "Habt Ihr die Djaradin gefunden und einige ihrer Werkzeuge erbeutet?", completion = "Da haben unsere Schmiede ja erst einmal genug zu tun. Vielen Dank, dass Ihr diese Werkzeuge gesammelt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[66942] = { id = 66942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Industriespionage", description = "Es mag nicht unumstritten sein, aber ich glaube, dass wir die Rituale der Primalisten studieren sollten, um neue Wege zu erlernen, elementare Energie zu kanalisieren. Ich bin sicher, wenn wir die Wege ihrer Magie erst verstehen, können wir sie nutzen, um alle möglichen innovativen Ingenieursarbeiten herzustellen.", sourceObjective = "Sammelt 10 ursprüngliche Rituale von den Primalisten der Dracheninseln für Gnoklin Quirkspule von der Drachenschuppenexpedition.", progress = "Habt Ihr einige ursprüngliche Rituale gefunden?", completion = "Mir wurde gesagt, dass die Primalisten die Zivilisation ablehnen und stürzen wollen. Ha! Der Schuss ging nach hinten los. Ihre Rituale werden die Inspiration für dutzende neue Dinge sein und ein neues goldenes Zeitalter der Technik einleiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[66943] = { id = 66943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schreibholz", description = "Wir haben bei unseren Studien auf den Dracheninseln ungewöhnliche Informationen herausgefunden. Beispielsweise verhält sich die Rinde der Treants, die von Verfallmagie betroffen sind, ähnlich wie Pergament aus Tierhäuten.\n\nDieses Rindenpergament ist merkwürdigerweise in der Lage, die Magie noch mächtigerer Inschriften zu binden. Wie nützlich! Könnt Ihr uns helfen, welches zu beschaffen?", sourceObjective = "Sammelt 15 Rindenpergamente von den verrottenden Treants der Dracheninseln für Dothenos vom Valdrakkenabkommen.", progress = "Konntet Ihr Rinde beschaffen?", completion = "Es ist seltsam. Diese Rinde fühlt sich an wie sehr feines Pergament. Allerdings setzt das unbehandelte Bündel in meinen Händen mir finstere Gedanken in den Kopf. Die Menge sollte vorerst genügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66944] = { id = 66944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pfauenpigmente", description = "Die Pfaue der Dracheninseln haben so hübsche bunte Federn! Ich bin mir sicher, wir können daraus Pigmente gewinnen, die unsere Schreiber als Tinte verwenden können.", sourceObjective = "Sammelt 8 Pfauenfedern von den Pfauen der Dracheninseln für Gnoklin Quirkspule von der Drachenschuppenexpedition.", progress = "Habt Ihr die Pfauenfedern aufgelesen?", completion = "So farbenfroh! Daraus werden wir sehr hübsche Pigmente herstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66945] = { id = 66945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eisige Tinte", description = "Die Eisbestien in den gefrorenen Biomen sondern eine sehr seltene und geheimnisvolle Flüssigkeit ab. Dank ihrer Eigenschaften eignet sich die Flüssigkeit perfekt als Bindemittel für unsere Tinten. Ich bin Linkshänder. Der Gedanke, meine Seiten nicht mehr zu verschmieren ist also sehr aufregend für mich.", sourceObjective = "Sammelt 20 eisige Exkremente von den Eisspinnen und Eisbären der Dracheninseln für Dothenos vom Valdrakkenabkommen.", progress = "Habt Ihr die eisigen Exkremente erlangt?", completion = "Vielen Dank für Eure harte Arbeit. Daraus können wir vorzügliche Tinte herstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66946] = { id = 66946, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprint des Azurblauen Gebirges", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[66947] = { id = 66947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprint des Azurblauen Gebirges - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[66948] = { id = 66948, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ankunft der Botschafterin", description = "Ich gebe zu, dass ich die Smaragdgärten mein Leben lang nicht verlassen habe, daher habe ich auch nie einen Zentauren getroffen und schon gleich gar keinen Sterblichen vom Festland.\n\nDennoch bin ich nicht auf einen freundschaftlichen Besuch hier, sondern vielmehr, um die Hilfe der Zentauren bei der Bergung unseres Schwursteins und dem Schutz der uns Anvertrauten zu erbitten.\n\nIch bin froh zu sehen, dass Ihr ebenfalls gekommen seid, um zu helfen. Es gibt viel zu besprechen.", sourceObjective = "Erfahrt mehr über die Lage in den Smaragdgärten.", completion = "Mehr freundliche Gesichter sind in der Tat ein willkommener Anblick.", sourceObjectiveStatus = "unverified-source-field" }
quests[66949] = { id = 66949, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmuckdiebe", description = "Die Gnolle haben eine große Sammlung von Schmuckstücken. Schmuckstücke der Tuskarr. Sie haben sie entweder aus unseren Dörfern gestohlen oder, schlimmer noch, den tapferen Tuskarr abgenommen, die im Kampf gegen sie gefallen sind. Diese Schmuckstücke sind unser Erbe und sollten bei uns sein.\n\nWenn Ihr einige zu mir zurückbringen könntet, bringe ich Euch die Techniken bei, mit denen sie hergestellt werden.", sourceObjective = "Sammelt 10 gestohlene Schmuckstücke von den Gnollen der Dracheninseln für Temnaayu von den Tuskarr von Iskaara.", progress = "Habt Ihr die gestohlenen Schmuckstücke von den Gnollen zurückgeholt?", completion = "Ich erkenne diese Schmuckstücke. Ich erinnere mich daran, wem sie einst gehört haben. Habt Dank, dass Ihr sie uns zurückgebracht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[66950] = { id = 66950, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herz eines Riesen", description = "Auf den Dracheninseln treiben sich verschiedene Riesen herum. Angeblich befinden sich in ihrem Kern wunderschöne Edelsteine. Normalerweise jagen wir die Kreaturen auf den Inseln nicht wegen ihrer Schätze, aber diese Riesen haben mächtig Unfrieden gestiftet.\n\nWenn wir die zerstörerischen Riesen sowieso aus dem Weg räumen, können wir dabei auch diese Juwelen einheimsen.", sourceObjective = "Sammelt 5 Riesenkerne von den Berg-, Eis- oder geschmolzenen Riesen der Dracheninseln für Temnaayu von den Tuskarr von Iskaara.", progress = "Habt Ihr ein paar Juwelen in den Riesen gefunden?", completion = "Das sind wirklich wunderhübsche Schätze.", sourceObjectiveStatus = "unverified-source-field" }
quests[66951] = { id = 66951, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Populationskontrolle", description = "In letzter Zeit haben wir bei verschiedenen Arten der Dracheninseln bedrohliche Überpopulationen beobachtet, insbesondere bei Felszähnen und Brüffelchen.\n\nWir wollen natürlich nichts verschwenden. Bitte sammelt so viele Bälge von diesen Kreaturen ein, wie Ihr könnt.", sourceObjective = "Sammelt 25 geborgene Bälge von den Felszähnen und Brüffelchen der Dracheninseln für Temnaayu von den Tuskarr von Iskaara.", progress = "Habt Ihr Euch um die Überpopulation gekümmert und einige Bälge zurückgebracht?", completion = "Vielen Dank, dass Ihr Euch der Situation angenommen und keine kostbaren Bälge verschwendet habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[66952] = { id = 66952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Gnolle teure Kleider", description = "Die Gnolle sind eine ständige Bedrohung durch ihre blutigen Überfälle und Angriffe auf die Expeditionen und die Bewohner der Dracheninseln. Wie also bleiben ihre Kleider so sauber?\n\nNachdem Ihr diese Plünderer bekämpft habt, würdet Ihr einige Proben ihrer getragenen Kleidung zur Analyse für mich sammeln?", sourceObjective = "Sammelt 20 Gnollstoffe von den Gnollen der Dracheninseln für Dothenos vom Valdrakkenabkommen.", progress = "Habt Ihr den Gnollstoff mitgebracht?", completion = "Vielen Dank für diese Proben. Auf den ersten Blick scheint es nur von den Tuskarr gestohlener Wildstoff zu sein. Aber um sicher zu gehen, werde ich veranlassen, dass unsere Schneider sich die Nähte ansehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66953] = { id = 66953, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flauschfaktor", description = "Die Schneider sind immer ganz erpicht darauf, das flauschige Fell von Riesenwildschafen in die Finger zu bekommen. Die Wolle ist besonders nützlich, um im eiskalten Gebirge der Dracheninseln zu überleben.", sourceObjective = "Sammelt 20 flauschige Felle von den Riesenwildschafen der Dracheninseln für Dothenos vom Valdrakkenabkommen.", progress = "Habt Ihr etwas von dem flauschigen Fell besorgt?", completion = "So flauschig! Ja, die sollten genügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66956] = { id = 66956, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenjäger Igordan" }
quests[66957] = { id = 66957, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Schatten im Eis", description = "Als ich das Lager Antonidas passiert habe, habe ich einige beunruhigende Gerüchte aufgeschnappt. Angeblich wurden überall in den Froststeppen verwundete Tiere gefunden. Von manchen blieben nicht mehr als Blutspritzer zurück.\n\nWas immer dahintersteckt, hat den Magiern ordentlich Angst eingejagt, und Tiere gibt es in der Gegend auch kaum noch.\n\nSeht Euch am Gipfel des Gletschers um. Ich würde meine Zwergenaxt darauf verwetten, dass ein Eliteraubtier sich dort herumtreibt.\n\nBringt mir eine Trophäe von ihm zurück, damit wir die Kirin Tor beruhigen können.", sourceObjective = "Untersucht den Gipfel des Gletschers, der Lager Antonidas überragt.", progress = "Seid vorsichtig. Was immer dieses Ding ist, es ist stark. Und unerbittlich.", completion = "Ein Eisriese? Bei Magnis bronzenem Bart... Und Ihr seid noch an einem Stück?\n\nIch bringe das zu den Kirin Tor. Vielleicht lassen sie uns dann in Frieden!", sourceObjectiveStatus = "unverified-source-field" }
quests[66958] = { id = 66958, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schützen und geleiten", description = "Ich habe kürzlich mit einigen Jägern aus Iskaara gesprochen und sie haben mir ein grausiges Bild beschrieben.\n\nOffenbar hat ein besonders mordlustiges Rhinozeros, Bluthorn, alle kleineren Brüffelche zu Brei verarbeitet.\n\nDie Brüffelche haben schon genug Konkurrenz im Azurblauen Gebirge, ohne dass sie sich darum sorgen müssen, dass ihre Herden von einem brutalen Eindringling ausgedünnt werden!\n\nBringt mir sein Horn. Ich würde gerne einen guten Eindruck bei unseren Tuskarrfreunden hinterlassen!", sourceObjective = "Erlegt Bluthorn östlich von Iskaara.", progress = "Denkt dran: Nehmt Euch vor seinen Hufen in Acht! Damit erwischen einen die Rhinozerosse meist.", completion = "Ausgezeichnete Arbeit, {name}! Das wird den Brüffelchen sehr helfen, zu gedeihen, und zeigt hoffentlich unseren Tuskarrnachbarn, dass wir ebenso treue Verwalter dieses Landes sind.\n\nWir können etwas von Bluthorn lernen. Nur, weil wir durch diese wunderschöne Gegend stapfen, heißt das noch lange nicht, dass wir hier tun und lassen können, was wir wollen!\n\nHinterlasst die Welt immer besser, als Ihr sie vorgefunden habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[66959] = { id = 66959, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besucht den Handelsposten", description = "<Ein Flugblatt, getragen vom Wind, landet in Euren Händen.>\n\nSeltene Antiquitäten aus ganz Azeroth! Edelste Waren für jeden Geschmack!\n\nDiese seltenen Schätze findet Ihr nur bei uns.\n\nBesucht uns in einem unserer Außenposten in Orgrimmar oder Dornogal und bewundert die Mysterien, die Euch erwarten!\n\n- Handelsposten Zen'shiri\n\n<Ihr müsst Euch anstrengen, um das Kleingedruckte entziffern zu können.>\n\nZeigt dieses Flugblatt für Bonushändlerdevisen vor!", sourceObjective = "Nehmt Eure Händlerdevisen aus der Truhe des Sammlers und besucht den Handelsposten.", progress = "Willkommen beim Handelsposten!\n\nWir haben Waren aus ganz Azeroth für Euch. Seht Euch ruhig um.", completion = "Ach, Ihr habt eins von unsren Flugblättern mitgebracht! Hier habt Ihr 'n paar Handelsdevis'n, die Ihr im Laden ausgeb'n könnt, wie versproch'n.\n\nWenn Ihr mehr davon hab'n wollt, müsst Ihr im Reisetagebuch vom Abenteuerführer schau'n, was es für Aktivitäten gibt. Schließt genug davon ab, dann geb'n wir Euch Devis'n und andere schöne Sach'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[66960] = { id = 66960, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kluzicc der Aufgestiegene" }
quests[66961] = { id = 66961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Jagd beitreten" }
quests[66963] = { id = 66963, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferschwierigkeiten", description = "Ich habe versucht, Vevesi klarzumachen, dass ich den Karren aus dem Schlamm bekomme.\n\nAber nein, er musste ja darauf bestehen, Magie zu benutzen... Und da seht Ihr, was er damit angerichtet hat.\n\n<Schlepperin Bennet seufzt.>\n\nIch versuche, Vevesi zur Einsicht zu bringen. Könntet Ihr währenddessen den Hügel zum Basislager hinauflaufen und Katalogisierer Wulferd erklären, dass er möglicherweise eine neue Kiste Kamerazubehör aus Boralus kommen lassen muss?", sourceObjective = "Berichtet Katalogisierer Wulferd im nahe gelegenen Basislager, dass seine Lieferung nicht so bald eintreffen wird.", completion = "<Katalogisierer Wulferd lacht.>\n\nGar kein Problem. Ich habe jede Menge Reservefilme im Handgepäck.", sourceObjectiveStatus = "unverified-source-field" }
quests[66964] = { id = 66964, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artefakte in den falschen Händen", description = "Wir haben hier Myriaden, nein, eine unüberschaubare Menge an Problemen!\n\nWo soll ich nur anfangen?!\n\nDie Kirin Tor haben eine Verschwörung der Splitterflammen aufgedeckt. Sie sind hinter einem Artefakt namens \"Valthrux\" her.\n\nEs verfügt über immense Kraft und könnte sogar... empfindsam sein?! Das ist ein exponentielles Wachstum an Gefahr, falls Ihr aufgepasst habt.\n\nAlia Segelstrahl ist mit ein paar Tuskarr nach Süden aufgebrochen, um die Splitterflammen zu untersuchen. Sie hätte schon längst zurück sein sollen.\n\nBitte findet sie und haltet die Splitterflammen davon ab, dieses Artefakt in die Finger zu bekommen!", sourceObjective = "Findet Alia Segelstrahl in den Verlorenen Ruinen im Azurblauen Gebirge.", completion = "Endlich etwas Glück! Wir könnten hier wirklich ein bisschen Hilfe brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66968] = { id = 66968, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Meute eindämmen", description = "<Nesingwary deutet neben den Pfad.>\n\nSeht Ihr diese Abdrücke im Schnee? \n\nYetispuren.\n\nIrgendwas muss sie aufgescheucht haben, wenn sie so nahe an der Straße jagen. Versucht, ihren Rudelführer ausfindig zu machen. Wir wollen nicht, dass sie anfangen, Reisende zu überfallen!\n\nWenn er eine besonders fiese Bestie ist, nehmt seinen Kopf mit. Das sollte die anderen abschrecken.", sourceObjective = "Erlegt Yetor nahe Rhonins Schild.", progress = "Vorsicht, mein Freund. Yetis jagen im Rudel.", completion = "Wow! Das nenn ich mal eine fiese Fresse... Ich bin froh, dass Ihr es lebendig zurückgeschafft habt!\n\nSo unangenehm es auch ist, hier ein Exempel statuieren zu müssen, es ist für die Yetis das Beste, wenn wir sie von den Straßen fernhalten.\n\nWie auch für uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[66969] = { id = 66969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klans der Ebenen", description = "Während Ihr auf die Ankunft der Botschafterin wartet, würde Sansok Khan gerne hören, wie Euer Treffen mit den Klans verlief. Sie hat mich geschickt, um Euch zu finden und zu bitten, sie im Zentrum von Maruukai für ein Gespräch zu treffen.", sourceObjective = "Meldet Euch bei Sansok Khan in Maruukai.", progress = "<Sansok Khan lächelt Euch an und heißt Euch willkommen.>", completion = "<Okir fasst in Worte, was Sansok Khan mit ihren Zeichen sagt.>\n\nEs gibt zwar viele Klans verschiedener Größen auf den Ebenen, doch die Shikaar, Teerai, Ohn'ir und Nokhud sind die mächtigsten unter ihnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[66970] = { id = 66970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ty'foon der Aufgestiegene" }
quests[66971] = { id = 66971, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Gesicht des Todes", description = "Sagt mir, <mein Freund/meine Liebe>, habt Ihr je dem Tod ins Gesicht geblickt?\n\n<Nesingwary macht eine dramatische Pause.>\n\nWas rede ich denn da? Natürlich habt Ihr das.\n\nSchließlich hat der Tod viele Gesichter.\n\nDie Tuskarr von Imbu sagen, eines dieser Gesichter lebt in diesen Hügeln. Seinen Namen nur auszusprechen, bedeutet, einen gewaltsamen, eisigen Tod heraufzubeschwören:\n\nFrostrachen.\n\n<Nesingwary sieht sich argwöhnisch um.>\n\nNun, jetzt müsst Ihr ihn jagen, allein schon mir zuliebe!", sourceObjective = "Erlegt Frostrachen nördlich der Winterpelzhöhle.", progress = "Trödelt nicht herum. Ich befinde mich hier in Lebensgefahr!", completion = "Ihr lebt!\n\nHa ha! Ich kann mir nicht vorstellen, was für einen Kampf Euch dieses Biest geliefert haben muss, als Ihr es in die Enge getrieben habt. Das Azurblaue Gebirge ist dank Euch ein wenig sicherer!\n\nTut mir einen Gefallen und seht nach meinem Pa...", sourceObjectiveStatus = "unverified-source-field" }
